import type { GlossaryTerm } from '@/lib/glossary-data'

export const EXT_TERMS_2: GlossaryTerm[] = [
  // ===== 紫微斗数 · 总论与星曜体系 =====
  {slug:'ziwei-doushu',name:'紫微斗数',pinyin:'Zǐ Wēi Dòu Shù',english:'Zi Wei Dou Shu (Purple Star Astrology)',category:'ziwei',shortDesc:'以紫微垣诸星布十二宫论命之术，天下第一神数。',detail:'紫微斗数是中国传统命理学的重要流派，相传源出宋代陈抟（希夷）一系，因以紫微垣为尊、按斗数布星而得名。它以农历出生年月日时起盘，将十二宫与上百颗星曜布于命盘，依星曜庙旺落陷、四化流转与三方四正的互动，推断性格、六亲、财运、事业与行运吉凶。论断重星曜组合与格局，与子平八字并称两大主流命术，号称天下第一神数。学紫微须先通安星、宫位、星性与四化四门功课。',related:['ziwei-xing','shi-er-gong','sihua']},
  {slug:'shisi-zhu-xing',name:'十四主星',pinyin:'Shí Sì Zhǔ Xīng',english:'The Fourteen Major Stars',category:'ziwei',shortDesc:'紫微斗数十四颗最重要的正曜，安星后最先确立的骨架。',detail:'十四主星即紫微斗数最重要的十四颗正曜，是全盘星曜的骨架：属北斗的有紫微、贪狼、巨门、廉贞、武曲、破军，属南斗的有天府、天机、天同、天相、天梁、七杀，太阳、太阴则列中天之星。十四主星性质各异，或主贵、或主财、或主福、或主开创，安入十二宫后还要看其所处的庙旺利陷以及同宫、会照、相夹的星曜，才能论其吉凶。主星之间的各种相会组合，正是紫微论命立格局的基础。',related:['ziwei-xing','tianji-xing','taiyang-xing']},
  {slug:'liu-ji-xing',name:'六吉星',pinyin:'Liù Jí Xīng',english:'Six Auspicious Stars',category:'ziwei',shortDesc:'左辅右弼文昌文曲天魁天钺六颗吉曜。',detail:'六吉星指左辅、右弼、文昌、文曲、天魁、天钺六颗吉曜。左辅右弼是紫微的左右臂膀，主得人扶助、地位安稳；文昌文曲为科甲文星，主文才学问与名声；天魁天钺为天乙贵人，主逢凶化吉、遇贵人提携。六吉入命多使人缘好、助力多、人生平顺，但吉星并不直接生财，须与正曜庙旺配合；若正曜无力而辅曜过多，反成依赖他人、因人成事的格局。吉星喜得其所，坐守命身、夹辅帝座各得其妙。',related:['zuofu','wenchang-xing','tiankui-xing']},
  {slug:'liu-sha-xing',name:'六煞星',pinyin:'Liù Shà Xīng',english:'Six Malefic Stars',category:'ziwei',shortDesc:'擎羊陀罗火星铃星地空地劫六颗凶曜。',detail:'六煞星指擎羊、陀罗、火星、铃星、地空、地劫六颗凶曜。擎羊主刑冲突发，陀罗主拖延反复，火星性烈而急，铃星阴狠突发，地空主落空理想化，地劫主破耗波折。然煞星并非全无用处：火铃可使贪狼爆发成格，羊陀有激发磨炼之功，空劫反主顿悟与淡泊。煞星得制、居庙或与吉化同宫，可化凶为用；若聚于命身或冲破吉格，则主刑伤破耗、成败起伏。凡论吉凶须观星曜整体组合，不可见煞即断凶。',related:['qingyang-xing','dikong-xing','huotan-ge']},
  {slug:'zuofu',name:'左辅星',pinyin:'Zuǒ Fǔ Xīng',english:'Assistant Star of the Left',category:'ziwei',shortDesc:'北斗助星，六吉之一，如帝座之左臂，主助力安稳。',detail:'左辅星五行属阳土，是紫微斗数最重要的吉曜之一，性质如辅佐帝座的左臂。左辅入命，主性格稳重端方、乐于助人，一生多得朋友、同事与长官扶助，行事顺遂有靠。它喜与紫微、天府等主星同宫或三方拱照，能增强主星的领导力与权威；与右弼分守或夹辅命身，古称辅弼拱主等吉格。左辅也代表善解人意的助力者与稳定的合作关系。若孤星独坐又逢煞忌，则助力减弱，反而依赖心重。',related:['youbi','ziwei-xing','liu-ji-xing']},
  {slug:'youbi',name:'右弼星',pinyin:'Yòu Bì Xīng',english:'Assistant Star of the Right',category:'ziwei',shortDesc:'北斗助星，六吉之一，主暗中相助与幕后斡旋。',detail:'右弼星五行属阴水，与左辅同为最重要的辅佐吉曜，性质含蓄而重在暗中相助。右弼入命，主为人温和谦让，多得他人暗中帮忙，做事常有贵人从旁成就。它较左辅更注重人际调和与幕后策划，适合协调、中介、幕后谋略一类角色。右弼喜与紫微同宫共守，或与左辅一前一后夹辅命身；得用之时，一生人脉丰沛、逢难有解。若逢煞忌冲破，则助力难显，易生依赖或受人所制。',related:['zuofu','ziwei-xing','liu-ji-xing']},
  {slug:'wenchang-xing',name:'文昌星',pinyin:'Wén Chāng Xīng',english:'Culture Star (Wen Chang)',category:'ziwei',shortDesc:'北斗文星，主科甲文书学术，正统文华之星。',detail:'文昌星五行属阳金，是正统的文星，主科甲、文书、学术与名声。文昌入命，主聪明好学、记忆力强，喜读书爱文艺，利考试升学与文职工作；为人温文有礼，重名誉。文昌文曲并称时，主才华横溢、文章出众；文昌亦主契约文书，入财帛、官禄等宫而与禄存、化禄同见时，古称利于经手文书契约之财。文昌落陷或被煞忌冲破，则文星受制，聪明反被聪明误，须防文书契约纠纷。',related:['wenqu-xing','liu-ji-xing','huake']},
  {slug:'wenqu-xing',name:'文曲星',pinyin:'Wén Qǔ Xīng',english:'Talent Star (Wen Qu)',category:'ziwei',shortDesc:'北斗文星，主才艺口才异路功名，亦带桃花。',detail:'文曲星五行属阴水，与文昌相对，性质偏重才艺、口才与异路功名。文曲入命，主口才流利、反应敏捷，富音乐、艺术、表演等才情，也代表经非正统管道获得的声名，如演艺、技艺、网络成名之类。文昌偏学术文章，文曲偏才艺辞令，故古有昌曲同度文章盖世之说。文曲亦为桃花星之一，与咸池、天姚同会时须防情欲纠缠。文曲化科，主才艺得名、考试有成；化忌则主文书口舌破财。',related:['wenchang-xing','huake','huaji']},
  {slug:'tiankui-xing',name:'天魁星',pinyin:'Tiān Kuí Xīng',english:'Noble Star of Heaven (Tian Kui)',category:'ziwei',shortDesc:'天乙贵人，六吉之一，主阳贵人明面扶助。',detail:'天魁星又名天乙贵人，五行属阳火，为六吉星之一，主科甲与现成的贵人。天魁入命或照会命宫，主一生多得长辈、长官、名流扶掖，遇困难常有人伸手相助，逢凶有解。古籍以魁为阳贵人，多应在男性或明面上的助力。天魁喜与天钺一坐命宫一照迁移，或分居命身，谓之坐贵向贵，主贵气显达。天魁亦主考试功名，入命宫三方四正且正曜庙旺者，多有学历或社会名望。若被煞忌冲破，则贵人缘薄。',related:['tianyue-xing','zuogui-xianggui','liu-ji-xing']},
  {slug:'tianyue-xing',name:'天钺星',pinyin:'Tiān Yuè Xīng',english:'Noble Star of Heaven (Tian Yue)',category:'ziwei',shortDesc:'玉钺贵人，六吉之一，主阴贵人暗中提携。',detail:'天钺星又名玉钺，五行属阴火，与天魁同为天乙贵人，主异性或暗中的扶助。天钺入命，主为人谦和知礼，一生多得女性长辈、异性朋友或幕后人士暗中提携，化解困厄。古以魁为阳贵、钺为阴贵，故天钺之助多来自阴柔一方。天钺喜会天魁，双贵临照，贵人运强；入身宫或迁移宫，出外易逢提携。天钺亦助考试名声，但力量较天魁含蓄。若与桃花星曜同度，须防贵人缘染上感情纠葛。',related:['tiankui-xing','liu-ji-xing','shen-gong']},
  {slug:'qingyang-xing',name:'擎羊星',pinyin:'Qíng Yáng Xīng',english:'Goat Blade Star (Qing Yang)',category:'ziwei',shortDesc:'六煞之首，刑刃之星，主刑伤冲突与突发。',detail:'擎羊星五行属阳金，为六煞之首，性质刚烈如刀，主刑伤、冲突与突发之事。擎羊入命，主性格果决冲动、敢作敢当，行事常有破釜沉舟之举，人生易有突发的竞争、争执或意外损伤。擎羊并非全凶：居庙旺之地或得吉星制化，反有激发斗志、一举成功之功，故有擎羊入庙威权出众之说。与陀罗夹禄存、夹化忌，则成羊陀夹忌之凶象。大限流年逢擎羊，主该运多竞争变动，须防血光官非。',related:['tuoluo-xing','liu-sha-xing','lucun-xing']},
  {slug:'tuoluo-xing',name:'陀罗星',pinyin:'Tuó Luó Xīng',english:'Spiral Star (Tuo Luo)',category:'ziwei',shortDesc:'六煞之一，主拖延反复、旧事纠缠与暗耗。',detail:'陀罗星五行属阴金，与擎羊并称羊陀，性质阴柔而拖沓，主拖延、反复与暗耗。陀罗入命，主做事缓慢磨蹭、迟疑不决，凡事易一波三折、好事多磨，也主旧事纠缠、难以了断。陀罗之凶较擎羊为缓而长，如钝刀割肉，主慢性损耗与心理折磨。然陀罗亦有耐力持久、后劲绵长的一面，得吉化制伏时，反而主能守成到底。陀罗夹命、夹忌或与煞星同宫，主运程迟滞，须防久拖生变。',related:['qingyang-xing','liu-sha-xing','huaji']},
  {slug:'huoxing-xing',name:'火星',pinyin:'Huǒ Xīng',english:'Mars Star (Huo Xing)',category:'ziwei',shortDesc:'六煞之一，性暴烈，主突发爆发，成火贪格。',detail:'火星五行属阳火，为六煞之一，性质暴烈，主突发、急速与爆发。火星入命，主性情急躁刚烈、行动力强，做事讲求快狠准，但也容易冲动闯祸、虎头蛇尾。火星喜与贪狼同宫或会照，成火贪格，主暴发横财、骤然发迹，但暴发之后亦须防骤败；火星居庙旺之地，反主工作有冲劲、掌实权。火星落陷又逢煞忌，主血光、火灾、官非等突发之灾。行限逢火星，主该运变动激烈，成败皆快。',related:['lingxing-xing','tanlang-xing','huotan-ge']},
  {slug:'lingxing-xing',name:'铃星',pinyin:'Líng Xīng',english:'Bell Star (Ling Xing)',category:'ziwei',shortDesc:'六煞之一，性阴狠，主暗发突发，成铃贪格。',detail:'铃星五行属阴火，与火星并称火铃，性质阴狠而主暗发，如暗夜铃声，事发突然却难防范。铃星入命，主外表平和而内心刚烈，心机较深，行事常不按牌理出牌；人生易有突发而起、来势汹汹的变化，吉则一夜成名，凶则灾祸骤至。铃星与贪狼同度成铃贪格，亦主横发，唯爆发力略逊火贪而持续较久。铃星落陷又逢忌煞，主暗耗、血光与口舌官非。断铃星须看其制化，得吉则化凶为权。',related:['huoxing-xing','tanlang-xing','lingtan-ge']},
  {slug:'dikong-xing',name:'地空星',pinyin:'Dì Kōng Xīng',english:'Sky Void Star (Di Kong)',category:'ziwei',shortDesc:'六煞之一，主落空理想化，亦主悟性与淡泊。',detail:'地空星五行属阳火，为六煞之一，性质主落空，如虚空无凭。地空入命，主性格超然淡泊、不拘小节，常有天马行空的构想，但落地成事较难，钱财与计划易成空，一生须防虚名虚利。然空劫亦主悟性：地空入命者多与宗教、哲学、玄学有缘，思考脱俗，反能看破得失。地空喜得吉星化解，则清高有格；若独坐命身又逢煞，则空忙一场、一事无成。行限逢地空，主该限计划落空或精神空虚。',related:['dijie-xing','liu-sha-xing']},
  {slug:'dijie-xing',name:'地劫星',pinyin:'Dì Jié Xīng',english:'Earth Robbery Star (Di Jie)',category:'ziwei',shortDesc:'六煞之一，主劫夺破耗，财来财去不安分。',detail:'地劫星五行属阴火，为六煞之一，性质主劫夺、破耗，如财物遭劫、中途生变。地劫入命，主钱财难聚，赚钱过程多波折，常有意外破耗或到手的利益又失去；性格上则较不安分，喜冒险求变，厌倦一成不变的生活。地劫并非全凶，与天机、巨门等动星同度，反而思维活络、敢于创新；与空亡同理，也主看淡得失、接近玄学。若与煞忌同缠命财二宫，主破财连连，须以守成为上。',related:['dikong-xing','liu-sha-xing','wuqu-xing']},
  // ===== 紫微斗数 · 四化 =====
  {slug:'sihua',name:'四化',pinyin:'Sì Huà',english:'Four Transformations',category:'ziwei',shortDesc:'化禄化权化科化忌，由天干引动，论命枢纽。',detail:'四化是紫微斗数论命的枢纽，指化禄、化权、化科、化忌四种星曜性质的变化，由天干引发：生年天干引发生年四化，大限、流年宫干再引发大限四化、流年四化。化禄主财禄顺畅与欲望满足，化权主掌权开创与责任压力，化科主声名文采与化解之功，化忌主执着困滞与是非损耗。同一颗星遇不同化曜吉凶截然不同，如天机化禄主善谋得利，天机化忌反主思虑成灾。断命先看四化飞入何宫，方知吉凶指向。',related:['hualu','huaquan','huake','huaji']},
  {slug:'hualu',name:'化禄',pinyin:'Huà Lù',english:'Transformation of Lu (Prosperity)',category:'ziwei',shortDesc:'四化之首，主财禄喜庆顺遂，吉力大增。',detail:'化禄是四化之首，性质随所化星曜而定，主财禄、喜庆与顺遂。星辰化禄，如旱苗得雨，吉力大增：主该星之吉性得以发挥，所求顺遂，钱财与机会随之而来。命宫化禄主一生衣食无缺、人缘佳，财帛宫化禄主财源顺畅，田宅宫化禄主房产丰足。然化禄亦主欲望与享受，若无吉星配合而独坐，反主因贪致耗。大限流年逢化禄入命身财帛等宫，主该运财喜临门，诸事可成。',related:['sihua','lucun-xing','caibo-palace']},
  {slug:'huaquan',name:'化权',pinyin:'Huà Quán',english:'Transformation of Quan (Authority)',category:'ziwei',shortDesc:'四化之一，主权力强势开创，魄力大增。',detail:'化权是四化之一，性质主权力、强势与开创，五行随星而定。星辰化权，如将帅得印，主该星魄力大增：说话有力、能掌权柄、负责任，事业上有开创局面之能。命宫化权，主一生有领导欲与担当，不喜受人支配；官禄宫化权，主事业有实权或技术专精；迁移宫化权，主出外能掌局面。然权星过旺，性情刚愎，人际关系易紧张。大限流年逢化权入宫，主该运掌握主动，宜进取不宜退守；忌星化权则主因强势而惹是非。',related:['sihua','guanlu-palace']},
  {slug:'huake',name:'化科',pinyin:'Huà Kē',english:'Transformation of Ke (Reputation)',category:'ziwei',shortDesc:'四化之一，主声名文采，以柔化解灾厄。',detail:'化科是四化之一，性质主声名、文采与化解，五行随星而定。星辰化科，主斯文有礼、名声渐起，如得功名牌匾，灾晦亦能化解于无形：凡化科入宫，可减凶增吉，主该宫之事有贵人、名誉、考试之利。命宫化科，主举止文雅、重名声，利考试升迁；官禄宫化科，主事业有声望或专业认证。化科之吉在于柔：以名望与修养化解冲突，故与煞忌同宫时，可使其凶性大为减轻。行限逢化科，主该运名誉提升，行事体面。',related:['sihua','wenchang-xing','guanlu-palace']},
  {slug:'huaji',name:'化忌',pinyin:'Huà Jì',english:'Transformation of Ji (Obstacle)',category:'ziwei',shortDesc:'四化之一，主困滞执着是非损耗，亦主毅力。',detail:'化忌是四化之一，性质主困滞、执着、是非与损耗，五行随星而定，是四化中最令人戒惧者。星辰化忌，如明珠蒙尘，吉星亦减色：主该宫之事多波折，易生是非、破耗与精神压力。然忌亦有执着之功：化忌入命反主毅力强、专心致志，逆境成事者不乏其人。断忌先看落宫：忌入财帛主财不顺，忌入夫妻主情多磨，忌入田宅主家宅烦扰。大限流年逢化忌，主该运该宫须保守忍耐；忌星得吉拱亦主先难后成。',related:['sihua','huaji','xingqiu-jiayin']},
  {slug:'sheng-nian-sihua',name:'生年四化',pinyin:'Shēng Nián Sì Huà',english:'Four Transformations of Birth Year',category:'ziwei',shortDesc:'以生年天干定四化，主先天人生取向。',detail:'生年四化是以生年天干查表所得的化禄、化权、化科、化忌，是紫微论命最根本的四化，代表先天带来的人生取向与课题。十干四化口诀：甲廉破武阳（廉贞化禄、破军化权、武曲化科、太阳化忌），乙机梁紫阴（天机化禄、天梁化权、紫微化科、太阴化忌），丙同机昌廉，丁阴同机巨，戊贪阴弼机，己武贪梁曲，庚阳武阴同，辛巨阳曲昌，壬梁紫辅武，癸破巨阴贪。看四化飞入何宫，可知命主一生最重之领域与先天功课。',related:['sihua','laiyin-gong']},
  // ===== 紫微斗数 · 财星桃花杂曜 =====
  {slug:'lucun-xing',name:'禄存星',pinyin:'Lù Cún Xīng',english:'Lu Cun (Prosperity Storage)',category:'ziwei',shortDesc:'北斗财星，主厚财储蓄，必被羊陀相夹。',detail:'禄存星五行属阳土，古称天禄，性质主厚实之财与储蓄。禄存入命，主一生衣食不缺，理财保守稳健，钱财能积能守，最宜守成置业。禄存必有擎羊、陀罗前后相夹，故得禄存之财亦伴刑克，古人谓禄存之财须防羊陀相夹，主财运虽稳而人事多有掣肘。禄存喜与吉星同宫，忌与空劫煞忌同度，否则财被冲破，反主财来财去。行限逢禄存，主该运财帛平稳，宜守不宜攻。',related:['qingyang-xing','tuoluo-xing','luma-jiaochi']},
  {slug:'tianma-xing',name:'天马星',pinyin:'Tiān Mǎ Xīng',english:'Tian Ma (Heavenly Horse)',category:'ziwei',shortDesc:'年系动曜，主奔波迁移驿动，成禄马交驰。',detail:'天马星性质主动，主奔波、迁移与变化。天马入命，主好动喜游、闲不下来，一生多走动、出差、搬迁之象，离乡背井反能发展。天马与禄存或化禄同宫、会照，称禄马交驰，主动中求财、越动越发，宜外出经商跑动；马遇空亡或落陷，则奔波无成、徒劳往返。马星亦为断应期之钥，流年大限逢天马冲动某宫，常有迁移变动之应。行限逢天马，主该运驿动频繁，须防劳碌伤身。',related:['lucun-xing','luma-jiaochi','qianyi-palace']},
  {slug:'hongluan-xing',name:'红鸾星',pinyin:'Hóng Luán Xīng',english:'Hong Luan (Red Phoenix)',category:'ziwei',shortDesc:'年系桃花喜曜，主婚庆喜事与姻缘。',detail:'红鸾星为年系杂曜之一，性质主婚庆、喜事与桃花。红鸾入命，主仪表俊秀、人缘讨喜，一生喜庆之事较多，婚姻缘分早现或较顺遂；入夫妻宫，主配偶貌美或婚姻带喜；入父母宫，主父母喜庆。红鸾与天喜常在对宫相照，一主婚嫁一主生育，合看六亲宫位可断嫁娶应期。红鸾亦是桃花星，与咸池、天姚同会或逢化忌，须防感情纠葛、先喜后忧。流年逢红鸾冲动夫妻宫，常为婚喜之应。',related:['tianxi-xing','xianchi-xing','fuqi-palace']},
  {slug:'tianxi-xing',name:'天喜星',pinyin:'Tiān Xǐ Xīng',english:'Tian Xi (Heavenly Joy)',category:'ziwei',shortDesc:'年系喜曜，主喜庆添丁，与红鸾对宫相照。',detail:'天喜星为年系杂曜，性质主喜庆、生育与添丁，与红鸾相对照而互为表里。天喜入命，主个性开朗带喜气，一生喜庆之期多；入子女宫，主子嗣有喜、生育顺利；入夫妻宫，主婚姻和乐。古诀以红鸾主嫁娶之期、天喜主孕育之喜，故流年大限逢红鸾天喜冲动夫妻、子女等宫，常为婚嫁添丁之应。天喜为喜神，能解部分凶厄；然逢煞忌亦主虚喜或喜中带忧，须细看所会星曜而定。',related:['hongluan-xing','zinv-palace','fuqi-palace']},
  {slug:'tianyao-xing',name:'天姚星',pinyin:'Tiān Yáo Xīng',english:'Tian Yao (Romance Star)',category:'ziwei',shortDesc:'月系桃花曜，主风流艳遇与才艺魅力。',detail:'天姚星为月系杂曜之一，性质主风流、艳遇与才艺，是重要的桃花星。天姚入命，主仪态风流、多才多艺，异性缘佳，感情世界丰富；性喜自由浪漫，不受礼法拘束。天姚与红鸾、咸池同会或逢化忌，主感情泛滥、易涉三角纠纷，须防因色破财惹祸。然天姚亦有风雅多情之正面，若与文昌文曲同度，反增艺术气质与魅力。行限逢天姚，主该运桃花浮动，感情之事多，宜守心定性。',related:['xianchi-xing','hongluan-xing','wenqu-xing']},
  {slug:'xianchi-xing',name:'咸池星',pinyin:'Xián Chí Xīng',english:'Xian Chi (Peach Blossom)',category:'ziwei',shortDesc:'年系桃花煞，主情欲魅力与酒色应酬。',detail:'咸池星又称桃花煞，为年系杂曜之一，性质主情欲、魅力与酒色应酬。咸池入命，主天生有吸引力、善交际应酬，异性缘旺，唯须防情欲过度、因色误事。咸池与天姚、红鸾并称三大桃花星，若同宫又逢化忌，主感情困扰、名誉受损；若正曜清吉，则反主才艺出众、人脉广阔，古有桃花得地反主聪明之说。咸池入夫妻宫主配偶有魅力，入福德宫主精神生活多彩，入身宫则一生异性助力与纠缠并存。',related:['tianyao-xing','hongluan-xing','wenqu-xing']},
  // ===== 紫微斗数 · 宫位与星曜强弱 =====
  {slug:'shi-er-gong',name:'十二宫',pinyin:'Shí Èr Gōng',english:'Twelve Palaces',category:'ziwei',shortDesc:'命盘基本框架，统摄人生十二面向。',detail:'十二宫是紫微斗数命盘的基本框架，安命宫后依逆时针方向依次排出：命宫、兄弟宫、夫妻宫、子女宫、财帛宫、疾厄宫、迁移宫、仆役宫（交友宫）、官禄宫、田宅宫、福德宫、父母宫，分别统摄人生的十二个面向。命宫为枢纽，其余十一宫各有所司：或主六亲缘分，或主财富事业，或主健康精神。论断时以命宫为中心，结合本宫星曜、三方四正及四化飞布逐宫观其吉凶。行运则看大限流年行至何宫，与该宫原局星曜重叠参断。',related:['ming-palace','sanfang-sizheng','shen-gong']},
  {slug:'xiongdi-gong',name:'兄弟宫',pinyin:'Xiōng Dì Gōng',english:'Siblings Palace',category:'ziwei',shortDesc:'主兄弟姐妹缘份、平辈关系与助力。',detail:'兄弟宫为紫微斗数十二宫之一，主兄弟姐妹、手足缘分及平辈间的关系。兄弟宫吉星坐守，主手足情深、兄弟得力，能得平辈扶持；逢煞忌冲破，则手足缘薄、各奔前程，或兄弟间多争执拖累。兄弟宫亦为成就位之一，古法常借以看母亲的健康及与母亲的缘分，并可参看交友倾向。行限至兄弟宫时，主该运与手足、同辈合作之事多；吉则得兄弟之助，凶则须防平辈拖累，以和为贵。',related:['shi-er-gong','ming-palace','fumu-palace']},
  {slug:'puyi-gong',name:'仆役宫',pinyin:'Pú Yì Gōng',english:'Friends and Servants Palace',category:'ziwei',shortDesc:'主朋友下属合伙社交，古称奴仆宫。',detail:'仆役宫又名交友宫，为紫微斗数十二宫之一，主朋友、下属、合伙人与社交圈。仆役宫吉，主交友广阔且多益友，下属得力，合伙有成；逢煞忌则主因友损财、被小人拖累，或下属背叛。现代论命常以此宫看人际网络与团队运：天机、天同入仆役宫主交友随和，紫微、天府入则朋友多具分量。仆役宫亦为成就位之一，古法借以看配偶之兄弟或母亲兄弟之概况。行限逢之，主该运人事应酬多，择友须慎。',related:['shi-er-gong','ming-palace','xiongdi-gong']},
  {slug:'shen-gong',name:'身宫',pinyin:'Shēn Gōng',english:'Body Palace',category:'ziwei',shortDesc:'后天宫位，随安入十二宫之一，主后天发展。',detail:'身宫是紫微斗数中与命宫相配的后天宫位，不另设宫，而是依出生月时另安，落于十二宫中之某一宫，随该宫星曜而断。一般以命宫主先天禀赋、性格根本，身宫主后天发展、中年以后的趋向及一生最执着之领域。身宫落财帛宫主重财，落官禄宫主重事业，落夫妻宫主重感情，落迁移宫主宜外出发展。论大限流年吉凶，身宫所在亦是重要参照；身宫得吉星坐守，后天努力多能补先天之不足。',related:['ming-palace','shi-er-gong','laiyin-gong']},
  {slug:'laiyin-gong',name:'来因宫',pinyin:'Lái Yīn Gōng',english:'Origin Palace',category:'ziwei',shortDesc:'主先天业因来处，飞星派尤重此宫。',detail:'来因宫是紫微斗数中较深层的概念，各派取法略异：大体以生年天干与命盘宫干相配合，寻出代表今生业力来处的宫位，即来因宫。飞星派论命尤重此宫，认为生年四化由此宫引出，命主一生的课题与际遇之源皆系于此：来因宫落财帛，此生纠缠于财；落夫妻，此生修习于情。参看此宫星曜与四化，可知先天带来之优势与功课。来因宫为古法精髓，宜与生年四化合参，不宜单独断吉凶。',related:['sheng-nian-sihua','feixing-pai','shen-gong']},
  {slug:'sanfang-sizheng',name:'三方四正',pinyin:'Sān Fāng Sì Zhèng',english:'Three Directions and Four Corners',category:'ziwei',shortDesc:'本宫加三合宫再加对宫，论命根本方法。',detail:'三方四正是紫微斗数论命的根本方法：以某一宫位为准，其本宫与三合方（相隔三宫的另两宫）合称三方，再加上正对面的对宫，共四宫，谓之四正。以命宫论，三方即命宫、财帛宫、官禄宫，四正再含迁移宫；看任何一宫，都须兼看其三方四正的星曜。命宫三方四正得吉星庙旺拱照，一生根基厚实；见煞忌冲破，则福力大减。大限流年亦同此理：吉凶不能只看本宫，须合观四正之会照才准。',related:['dui-gong','ming-palace','sanhe-pai']},
  {slug:'dui-gong',name:'对宫',pinyin:'Duì Gōng',english:'Opposite Palace',category:'ziwei',shortDesc:'本宫正对面之宫，星曜以照论，力量次同宫。',detail:'对宫又称照宫，是与本宫正对面、相隔六个宫位的宫位，如命宫之对宫即迁移宫，夫妻宫之对宫即官禄宫。紫微斗数论星曜关系，对宫之星谓之照，力量仅次于同宫：吉星在对宫拱照，本宫受益；煞忌在对宫冲照，本宫受制。故看命宫须兼看迁移宫，看财帛须兼看福德宫，本宫星曜单薄时，对宫往往决定吉凶。大限流年行至对宫冲照本命宫之时，常为运程转折、事有应验之期。',related:['sanfang-sizheng','qianyi-palace','ming-palace']},
  {slug:'miao-wang-li-xian',name:'庙旺利陷',pinyin:'Miào Wàng Lì Xiàn',english:'Miao Wang Li Xian (Star Brightness Levels)',category:'ziwei',shortDesc:'星曜亮度分级，论吉凶先看落宫强弱。',detail:'庙旺利陷是紫微斗数判断星曜强弱的基本概念：星曜安入各宫后，因得令失令而有亮度之别，古人分庙、旺、利、平、陷等层级（诸书细分略异）。庙为最佳，星力完全发挥；旺次之，力量强劲；利为得地可用；平为平平；陷为失地，星性难以发挥，吉星减吉、煞星增凶。论断时须先看星曜庙旺利陷，再看吉凶组合：同一颗七杀，庙旺则为将才，落陷则成凶暴。行限吉凶亦须先论落宫亮度，庙旺之吉方为实吉。',related:['geju','ziwei-xing','shisi-zhu-xing']},
  // ===== 紫微斗数 · 格局 =====
  {slug:'geju',name:'格局',pinyin:'Gé Jú',english:'Patterns (Ge Ju)',category:'ziwei',shortDesc:'星曜组合命名断贵贱，成格层次分明。',detail:'格局是紫微斗数论命的高阶方法：将命身宫、三方四正内的星曜组合按其排列模式命名，如杀破狼、紫府同宫、机月同梁、月朗天门等，一经成格，即按该格古诀断其贵贱贫富与人生类型。成格者一生轨迹鲜明、格局层次高，不成格者则以单星单宫细论。断格局须注意三点：一要星曜庙旺且成格条件齐备，二要无煞忌冲破（否则破格），三要看行限能否引动。格局只论大方向，仍须配四化与宫位细断流年吉凶。',related:['shapolang','zifu-tonggong','jiyue-tongliang']},
  {slug:'shapolang',name:'杀破狼',pinyin:'Shā Pò Láng',english:'Sha Po Lang Pattern',category:'ziwei',shortDesc:'七杀破军贪狼三合会照，主变动开创之命。',detail:'杀破狼是紫微斗数最著名的格局之一，指七杀、破军、贪狼三星在三方四正会齐（多在四马之地成局）。杀破狼格局者一生多变动、大起大落，不喜安分守己，具有开创、冒险与破坏重建的精神，适合军警、工程、创业、演艺等动中求成的行业。与机月同梁的安定公职格局恰成对比，古有杀破狼生涯逐浪之说。成格者须见吉化制化，方能在变动中累积成就；否则一生奔波、成败反复，宜动不宜静。',related:['qisha-xing','posun-xing','tanlang-xing']},
  {slug:'zifu-tonggong',name:'紫府同宫',pinyin:'Zǐ Fǔ Tóng Gōng',english:'Zi Wei and Tian Fu in Same Palace',category:'ziwei',shortDesc:'紫微天府同守一宫，帝座得库之贵格。',detail:'紫府同宫指紫微与天府两颗帝后级主星同守一宫（寅申二宫之一成局），为紫微斗数著名贵格。紫微为北斗帝星，天府为南斗财库，二星同宫，帝座得库，主性格稳重、气度恢弘，兼具领导力与理财守成之能，一生地位财富皆有可观，多掌权柄或管理大财。此格亦须防星力过强而固执自恃；且天府库藏须得禄存、化禄充实方为大富，若逢空劫冲破，则库破财散，贵气大减。',related:['ziwei-xing','tianfu-xing','lucun-xing']},
  {slug:'riyue-tonggong',name:'日月同宫',pinyin:'Rì Yuè Tóng Gōng',english:'Sun and Moon in Same Palace',category:'ziwei',shortDesc:'太阳太阴同宫守命，如日月并辉之贵格。',detail:'日月同宫又称日月合璧，是紫微斗数中的贵格之一，指太阳、太阴两颗中天主星同宫守命，如日月并辉。日主贵显、月主富足，日月同宫之人聪明俊秀、福泽深厚，性情外柔内刚，能兼顾事业与家庭，古人视为阴阳调和之大吉之象。此格须二星庙旺不陷方全其美，若日月失辉落陷则徒有其名，须防早年劳碌、起伏较大。逢化禄化权化科同会，更主名利双收、成就非凡。',related:['taiyang-xing','taiyin-xing','riyue-fanbei']},
  {slug:'riyue-fanbei',name:'日月反背',pinyin:'Rì Yuè Fǎn Bèi',english:'Sun and Moon Reversed',category:'ziwei',shortDesc:'日月落陷失辉，主贵气不显、多劳少成。',detail:'日月反背是紫微斗数中与日月同宫、日月并明相对的不利格局，指太阳、太阴落陷失辉或分布失常，如日沉西海、月暗无光。日月反背入命，主贵气不显、怀才不遇，早年易劳碌奔波，与父母缘薄或聚少离多；性格上或有阴晴不定、忽明忽暗之象。断此格须细看二星实际落宫亮度：若行限逢吉化补救，或迁移宫见日月庙旺，亦可后天翻转、晚运有成。古诀认为此格最忌再逢煞忌，须防一生颠簸。',related:['taiyang-xing','taiyin-xing','riyue-tonggong']},
  {slug:'jiyue-tongliang',name:'机月同梁',pinyin:'Jī Yuè Tóng Liáng',english:'Ji Yue Tong Liang Pattern',category:'ziwei',shortDesc:'机阴同梁四星会照，主公职吏人之命。',detail:'机月同梁是紫微斗数著名格局，指天机、太阴、天同、天梁四星在三方四正会齐守照，古诀称机月同梁作吏人。此格之人聪明细心、温文守分，最适合公务员、公司职员、技术工程、文教等安定职业，一生平稳少波，以专业与耐性立身，多能在体制内稳步升迁。四星中以天机主谋略、天梁主荫护，故亦多智谋型幕僚人才。此格格局平稳，不宜冒险创业；若四星落陷又逢煞，则一生劳碌清贫，须防机关算尽。',related:['tianji-xing','taiyin-xing','tiantong-xing','tianliang-xing']},
  {slug:'shizhong-yinyu',name:'石中隐玉',pinyin:'Shí Zhōng Yǐn Yù',english:'Jade Hidden in Stone',category:'ziwei',shortDesc:'巨门得吉化如石中藏玉，大器晚成之格。',detail:'石中隐玉是紫微斗数格局之一，指巨门星坐命而获吉化（尤以得化禄、化权、化科入命或三方照会者为真），如美玉藏于顽石，光华内蕴。巨门本为暗曜，主口舌是非，一旦得吉化磨洗则化暗为明：命主早年多平淡压抑、不受重视，中年以后才华渐显，终能脱颖而出、名成利就，故称大器晚成之格。此格最重吉化之力，若巨门无吉化而逢煞忌则不成格，反主口舌官非、一生郁郁。',related:['jumen-xing','sihua','huake']},
  {slug:'yuelang-tianmen',name:'月朗天门',pinyin:'Yuè Lǎng Tiān Mén',english:'Bright Moon at Heaven Gate',category:'ziwei',shortDesc:'太阴独坐亥宫守命，清辉贵显之格。',detail:'月朗天门是紫微斗数著名贵格，指太阴星独坐亥宫守命（亥为天门之位），月色清辉，故名。此格之人性情温雅、聪慧内敛，心思细腻而胸怀大志，多得长辈、女性贵人相助，一生福泽绵长，男命亦主气质清贵。亥宫太阴为庙旺之地，最喜无煞冲破；若再逢化禄化科及吉星拱照，主大贵之命，晚运尤佳。若被煞忌冲破，则清辉蒙尘，主徒有才志而际遇多蹇，须防感情用事。',related:['taiyin-xing','tiankui-xing','tianyue-xing']},
  {slug:'rili-zhongtian',name:'日丽中天',pinyin:'Rì Lì Zhōng Tiān',english:'Sun at High Noon',category:'ziwei',shortDesc:'太阳坐午宫守命，如日中天之大贵格。',detail:'日丽中天又称日照雷门、太阳在午，是紫微斗数著名贵格，指太阳星坐守午宫命宫（午为正南中天之地），如日中天，光芒万丈。此格之人光明磊落、气度恢弘，具领导才能与博爱胸怀，一生贵人多助，名望地位显达，利从政、管理、公益等阳刚之事。太阳在午为庙旺之极，最喜辅弼昌曲拱照，若逢化禄化权主大贵；唯忌落陷受制或逢巨门遮蔽，则光辉受损。此格贵而多劳，宜向外发展、广结善缘。',related:['taiyang-xing','guanlu-palace','qianyi-palace']},
  {slug:'fuxiang-chaoyuan',name:'府相朝垣',pinyin:'Fǔ Xiàng Cháo Yuán',english:'Treasury and Minister Facing the Court',category:'ziwei',shortDesc:'天府天相拱照朝会，主贵显而宜守成。',detail:'府相朝垣是紫微斗数格局之一，指天府、天相双星在命宫三方四正拱照朝会（多与紫微坐命或身宫共见），如百官朝拱紫微垣。此格之人稳重得体、进退有度，天生具管理统筹之才，一生多得贵人提携，事业上易掌行政、财务等实权，中年以后成就渐显。府相为南斗之库印，主守成亦主辅佐，故此格宜在体制内发展或与人合作，不宜孤军冒险。若被空劫煞忌冲破，则朝拱无力、徒具其表，须防虚名。',related:['tianfu-xing','tianxiang-xing','ziwei-xing']},
  {slug:'junchen-qinghui',name:'君臣庆会',pinyin:'Jūn Chén Qìng Huì',english:'Emperor and Ministers in Celebration',category:'ziwei',shortDesc:'紫微坐命得群臣拱会，最尊贵吉格之一。',detail:'君臣庆会是紫微斗数著名吉格，指紫微坐命，三方四正得左辅、右弼、文昌、文曲、天魁、天钺等吉曜拱会，如君王临朝、群臣庆贺。此格之人天生具领袖气质与号召力，得众人拥戴，一生贵显，事业有成、名望卓著，多为一方之主或团体核心。君臣庆会之成，贵在辅弼昌曲魁钺齐全且庙旺；若辅星不全或受煞忌冲破，则君弱臣散，主孤高寡助、怀才不遇。行限得吉再会，为发迹之期。',related:['ziwei-xing','zuofu','tiankui-xing']},
  {slug:'caiyin-jiayin',name:'财荫夹印',pinyin:'Cái Yìn Jiā Yìn',english:'Wealth and Blessing Clamping the Seal',category:'ziwei',shortDesc:'天相被天梁禄存相夹，福荫财禄兼备。',detail:'财荫夹印是紫微斗数吉格之一，指天相（印星）坐守命宫或身宫，其左右两邻宫恰为天梁（荫星）与化禄或禄存（财星）相夹，谓之财荫夹印。此格之人一生福荫深厚，财禄与长辈庇护兼得，行事安稳有靠，多能继承家业或得贵人栽培，中晚年富足，与刑囚夹印之凶恰成对照。断此格须天相庙旺无煞，若被煞忌冲照则夹力受损。行限逢此夹辅，主该运财喜临门、逢凶化吉。',related:['tianxiang-xing','tianliang-xing','lucun-xing']},
  {slug:'xingqiu-jiayin',name:'刑囚夹印',pinyin:'Xíng Qiú Jiā Yìn',english:'Punishment and Prison Clamping the Seal',category:'ziwei',shortDesc:'天相被天刑廉贞相夹，主官非刑伤之凶格。',detail:'刑囚夹印是紫微斗数凶格之一，与财荫夹印相对，指天相（印星）坐命或坐身宫，左右两邻宫为天刑与廉贞（化气为囚，逢化忌更验）相夹。此格之人一生易因是非刑讼而受累，行事须防文书契约之灾与官非牢狱之险，尤须注意法律边界与人际纠纷。断此格还须看天相本身庙陷及煞忌多寡：若天相庙旺得吉，刑囚之凶可减；若又逢煞忌冲照，则凶性大增。行限逢之，主该运须防官非刑伤，宜守不宜争。',related:['tianxiang-xing','lianzhen-xing','huaji']},
  {slug:'sanqi-jiahui',name:'三奇嘉会',pinyin:'Sān Qí Jiā Huì',english:'Three Wonders Auspicious Meeting',category:'ziwei',shortDesc:'化禄化权化科三方会齐，大贵之格。',detail:'三奇嘉会是紫微斗数最尊贵的格局之一，指化禄、化权、化科三吉化同入命宫三方四正会齐（又称科权禄拱），如三星拱照。此格之人一生贵气洋溢，才华、权力与财禄兼备，多能出人头地、名利双收，成就非凡，古称三奇嘉会万世亨通。然三奇亦有虚实之分：三方四正汇聚者力大，若仅聚于一隅则力减；又须正曜庙旺作根基，若命弱而奇强，或三奇逢煞忌冲破，则成虚花之象，贵而不实。行限再逢引动，主大运发越。',related:['hualu','huaquan','huake']},
  {slug:'luma-jiaochi',name:'禄马交驰',pinyin:'Lù Mǎ Jiāo Chí',english:'Lu and Horse in Full Gallop',category:'ziwei',shortDesc:'禄存化禄与天马相会，动中求财之吉格。',detail:'禄马交驰是紫微斗数吉格之一，指禄存（或化禄）与天马同宫、对拱或三合相会，如财马相随。此格主动中求财、越动越发：命主宜外出发展、异地经营，凡跑动、运输、贸易、外务之财皆利，古称禄马交驰发财远乡。若禄马落于财帛、迁移等宫，发迹更显；忌落空亡或被空劫冲破，则马失其蹄，徒劳奔波。行限逢禄马交驰，主该运宜动不宜静，出门有财喜，唯须防劳碌。',related:['lucun-xing','tianma-xing','caibo-palace']},
  {slug:'huotan-ge',name:'火贪格',pinyin:'Huǒ Tān Gé',english:'Huo Tan Pattern (Mars + Tan Lang)',category:'ziwei',shortDesc:'贪狼会火星，主暴发横财，亦防骤败。',detail:'火贪格是紫微斗数著名爆发格局，指贪狼星与火星同宫或三方会照。贪狼本主欲望才艺，火星主突发爆发，二星相遇如烈火烹油，主突发横财、骤然发迹，一夜暴富或一夜成名皆有可能，尤以居庙旺之地为验。此格发迹多在中年以前，然暴发之财来得快去得也快：若命主根基不稳或行限再见煞忌，暴发之后每有骤败之险，故宜见好即收。古诀称火贪同格横发横破，发时须守，破时勿馁。',related:['tanlang-xing','huoxing-xing','lingtan-ge']},
  {slug:'lingtan-ge',name:'铃贪格',pinyin:'Líng Tān Gé',english:'Ling Tan Pattern (Bell + Tan Lang)',category:'ziwei',shortDesc:'贪狼会铃星，主暗中布局、晚发之横财格。',detail:'铃贪格是紫微斗数著名爆发格局，指贪狼星与铃星同宫或三方会照，与火贪格并称两大横发格局。铃星主阴狠突发，其爆发力较火星略缓，但持续与暗中发力之性更强：此格之人平时不显山露水，一旦时机成熟，便暗中布局、一举成功，暴发多在中年以后或属晚发，成果亦较火贪格稳固。铃贪格亦有横发横破之象，发迹之后须防转折；若能守成，反主大富。断此格须贪狼庙旺，落陷则吉力大减。',related:['tanlang-xing','lingxing-xing','huotan-ge']},
  {slug:'juji-tonglin',name:'巨机同临',pinyin:'Jù Jī Tóng Lín',english:'Ju Men and Tian Ji Together',category:'ziwei',shortDesc:'天机巨门同宫守命，主聪明善辩之格。',detail:'巨机同临是紫微斗数格局之一，指天机、巨门二星同宫守命（卯酉二宫之一成局），故又称巨机同临格。天机主智谋机变，巨门主口才是非，二星同临，命主聪明绝顶、能言善辩，思维敏捷而带批判性，适合法律、外交、咨询、写作、企划等以口舌智谋立身的行业。此格若得化禄化权化科及吉星拱照，则口舌化为金声玉振，名成利就；若无吉化又逢煞忌，则聪明反被聪明误，主口舌官非缠身。行限吉凶起伏较大。',related:['jumen-xing','tianji-xing','sihua']},
  {slug:'zuogui-xianggui',name:'坐贵向贵',pinyin:'Zuò Guì Xiàng Guì',english:'Sitting Noble Facing Noble',category:'ziwei',shortDesc:'魁钺分居命身对宫，贵人前后呼应。',detail:'坐贵向贵是紫微斗数格局之一，指天魁、天钺分居命宫与迁移宫（一坐一向）或分守命身二宫，贵人前后呼应。此格之人一生贵人运特强：行事宜有人扶，遇难常得化解，出外易逢提携，多能借他人之力平步青云；自身亦知礼重情，广结善缘。古以坐贵向贵主科甲功名，命主多有学历或社会地位。若魁钺又被煞忌冲破，或命宫正曜无力，则贵人缘薄，须防得而复失。行限逢之，主该运贵人临门，宜主动求进。',related:['tiankui-xing','tianyue-xing','qianyi-palace']},
  {slug:'wenxing-gongming',name:'文星拱命',pinyin:'Wén Xīng Gǒng Mìng',english:'Literary Stars Arching the Life',category:'ziwei',shortDesc:'昌曲拱照命宫，主文华出众利考试。',detail:'文星拱命是紫微斗数格局之一，指文昌、文曲双文星在命宫三方四正拱照朝会（或昌曲夹命），如文星拱卫。此格之人聪明好学、文采斐然，气质儒雅，读书考试运佳，适合学术、文教、出版、传媒等文职工作，一生以才艺学问立身扬名。文星拱命若再会化科，主考试成名、文名远播；若昌曲落陷或逢煞忌，则才高而运蹇，徒有文名难展抱负。行限逢文星引动，利考试、发表、升迁等文书喜庆之事。',related:['wenchang-xing','wenqu-xing','huake']},
  // ===== 紫微斗数 · 行运 =====
  {slug:'daxian',name:'大限',pinyin:'Dà Xiàn',english:'Major Decade Limit',category:'ziwei',shortDesc:'十年一运之主运，从命宫依阴阳顺逆排布。',detail:'大限是紫微斗数推运的主要单位，每十年行一宫，从命宫起依性别顺逆排列：阳男阴女顺行，阴男阳女逆行；起限岁数由五行局决定，如木三局者命宫即三至十二岁，金四局者四至十三岁，依此类推。断十年运势，看大限所落宫位星曜、四化飞布及其与命宫、原盘格局的互动：吉限主十年顺遂，宜进取；凶限主十年困顿，宜守成。大限与流年须合看，方知逐年应验之机，故有大限管十年、流年定应期之说。',related:['wuxing-ju','xiaoxian','liunian']},
  {slug:'xiaoxian',name:'小限',pinyin:'Xiǎo Xiàn',english:'Minor Annual Limit',category:'ziwei',shortDesc:'一年一宫的辅助小运，主一年内细事。',detail:'小限是紫微斗数推流年之内细运的辅助单位，一年行一宫，依生年支与性别安于特定宫位后逆行十二宫（起法口诀有男起寅女起申之异，各派略有出入），与流年太岁并行。小限主一年之内较细微之事：情绪起伏、健康状况、人际小事、感情细节等。论断时以流年大方向为纲，以小限所见为目，细察该年宫位星曜与流煞的引动。小限逢吉星化吉，主该年内心顺遂、小有喜庆；逢煞忌则心绪不宁、琐事缠身。',related:['daxian','liunian','liuyue']},
  {slug:'liunian',name:'流年',pinyin:'Liú Nián',english:'Yearly Fortune (Liu Nian)',category:'ziwei',shortDesc:'太岁流年，一岁一宫，断当年运势。',detail:'流年又称太岁流年，是紫微斗数逐年推运的单位，一岁行一宫：以流年地支所对应的宫位为流年命宫，如逢子年则看子位宫垣。断当年运势，以流年命宫星曜为主，参看流年财帛、官禄等宫及流年四化飞布，并与大限、本命格局重叠参断：流年命宫逢吉化拱照，主当年顺遂有喜；逢煞忌冲破本命关键宫位，主当年有灾有变。流年宫位与原命宫重叠或冲照之岁，常为人生大事应验之期。',related:['daxian','liuyue','dui-gong']},
  {slug:'liuyue',name:'流月',pinyin:'Liú Yuè',english:'Monthly Fortune (Liu Yue)',category:'ziwei',shortDesc:'按月推运，断月内吉凶与应期。',detail:'流月是紫微斗数按月推运的单位，将流年细分为十二个月：一般以流年命宫起正月顺行十二宫（亦有以斗君起月之法），逐月看流月命宫星曜与四化的引动。断月内之事，以大限管十年、流年管一年、流月管一月为层级：月内吉凶应于流月宫位与原局星曜的交会，逢吉化入流月命身，主该月顺遂有喜；逢煞忌冲照，则该月事多阻滞。流月精度较粗，多用于断应期与一时之得失，宜与流日合参。',related:['liunian','liuri','xiaoxian']},
  {slug:'liuri',name:'流日',pinyin:'Liú Rì',english:'Daily Fortune (Liu Ri)',category:'ziwei',shortDesc:'逐日细推之运，多用于断应期择日。',detail:'流日是以日为单位的最细推运层次，由流月再细分，一日行一宫（起法各派略异，多以流月命宫或特定宫位起朔日）。流日用于断具体应期：如流年流月已断某宫有吉凶大事，再看流日行至何宫以定发生之日；或用于择日办事，看当日星曜吉凶。由于逐日星曜变动细微，民间推算流日多与斗君、流曜合用，精确度有限，宜粗不宜细。凡重大抉择之日，宜再参当日黄历与奇门择时，多重印证为妥。',related:['liuyue','liunian','xiaoxian']},
  // ===== 紫微斗数 · 安星法与流派 =====
  {slug:'anxingfa',name:'安星法',pinyin:'Ān Xīng Fǎ',english:'Star Placement Method',category:'ziwei',shortDesc:'紫微排盘全部星曜布列口诀规则的总称。',detail:'安星法是紫微斗数排盘的基本功，指按出生年月日时依口诀布列星曜的全部规则，包括：安命宫身宫（寅宫起正月顺数至生月，命宫逆数生时、身宫顺数生时）、定十二宫、依五行局与生日查诀安紫微、由紫微安天府及其余主星、再安辅星杂曜（左辅右弼昌曲魁钺羊陀火铃空劫、禄存天马红鸾等）、排大限小限。各家口诀大同小异，惟安星细则须熟记：星曜错一位则全盘皆非，故古来学紫微必先过安星一关。',related:['ziwei-xingjue','wuxing-ju','paipan']},
  {slug:'wuxing-ju',name:'五行局',pinyin:'Wǔ Xíng Jú',english:'Five Elements Bureau',category:'ziwei',shortDesc:'水二木三金四土五火六，定紫微与大限起点。',detail:'五行局是紫微斗数排盘的重要参数，指以命宫干支查纳音五行所得的局数，共五种：水二局、木三局、金四局、土五局、火六局。五行局有两个作用：一是作为推算紫微星落宫的依据（结合生日查紫微星诀）；二是决定大限的起始岁数，如木三局者大限自三岁起算。五行局亦隐示命主先天气质与人生节奏：水二局灵动机敏，木三局进取生长，金四局刚毅决断，土五局厚重守成，火六局爆发热烈。断命时局数常与紫微星诀连用。',related:['ziwei-xingjue','anxingfa','daxian']},
  {slug:'ziwei-xingjue',name:'紫微星诀',pinyin:'Zǐ Wēi Xīng Jué',english:'Zi Wei Star Placement Formula',category:'ziwei',shortDesc:'依五行局与生日推紫微星所在宫位的口诀。',detail:'紫微星诀是安紫微星所依据的口诀技法：已知命宫干支所属五行局后，以生日与该局局数相配，依商数定宫、余数行度的原则，从寅宫起算，推得紫微星所在宫位。古诀将各局生日逐一列明，如某局某日紫微在某宫之类，习者多背口诀或以掌诀推算。紫微星定，则天府星自其对面逆向安置，其余十二颗主星依紫微、天府两系相对位置排布，全盘星曜乃定。此诀为安星之首，错则满盘皆错。',related:['anxingfa','wuxing-ju','ziwei-xing']},
  {slug:'paipan',name:'排盘',pinyin:'Pái Pán',english:'Chart Casting',category:'ziwei',shortDesc:'依生辰将紫微命盘完整排出的起盘过程。',detail:'排盘又称起盘，指依出生年月日时将紫微斗数命盘完整排出，是论命的第一步。其程序为：先安命宫身宫与十二宫位，再定五行局、依紫微星诀安十四主星，续安左辅右弼等辅星及禄存、天马、红鸾、天喜等杂曜，再以生年天干布生年四化，最后排大限小限及流年神煞。古今排盘以历法为准绳，须先换算农历与时辰（子时换日之争论各派不同）。现代多以软件排盘，惟学者仍宜通晓安星原理，方能识盘之正误、断之精粗。',related:['anxingfa','wuxing-ju','ziwei-xingjue']},
  {slug:'sanhe-pai',name:'三合派',pinyin:'Sān Hé Pài',english:'San He School (Three Harmonies)',category:'ziwei',shortDesc:'古法流派，重星曜庙旺与三方四正格局。',detail:'三合派是紫微斗数的主要流派之一，又称古法派，论命以星曜性质与庙旺利陷为本，重十二宫的三方四正会照，故称三合派。此派断命注重命盘静态格局：看正曜组合、辅煞分布、成格与否，再配大限流年推运；承传有绪，代表人物如中州派一系陆斌兆、王亭之等。三合派对四化亦用，但不作过度飞化，主张星性为本、四化为用。习此派者须熟记诸星性质与格局古诀，论断以稳健著称。',related:['feixing-pai','sanfang-sizheng','geju']},
  {slug:'feixing-pai',name:'飞星派',pinyin:'Fēi Xīng Pài',english:'Fei Xing School (Flying Stars)',category:'ziwei',shortDesc:'重宫干飞化四化与来因宫，断事具体。',detail:'飞星派是紫微斗数的重要流派，与三合派相对，论命以四化为枢纽：以宫干飞化为主，尤其重视来因宫与生年四化，将化禄化权化科化忌由本宫飞入他宫，看其串联以断吉凶来去，称飞星四化。此派在星曜为体、四化为用之外更重飞化之往来，论断精于断应期与事情缘由，对来因宫、自化、体用尤为讲究。飞星派因断事具体、反应迅速而流行，然飞化规则门派间分歧较大，学者宜择一师承，切勿混参。',related:['sanhe-pai','laiyin-gong','sheng-nian-sihua']},
  // ===== 奇门遁甲 · 总论与基础 =====
  {slug:'qimen-dunjia',name:'奇门遁甲',pinyin:'Qí Mén Dùn Jiǎ',english:'Qi Men Dun Jia',category:'qimen',shortDesc:'古传三式之首，以九宫八门九星八神断吉凶。',detail:'奇门遁甲是中国传统术数中最高深的预测术之一，与太乙、六壬并称三式，居三式之首。它融合阴阳五行、干支历法与洛书九宫，以乙丙丁三奇、戊己庚辛壬癸六仪布于九宫，配休生伤杜景死惊开八门、天蓬等九星与八神，按时辰起局，用于预测人事吉凶、择时择方与趋吉避凶。相传始于黄帝战蚩尤时九天玄女授书，历代多用于兵家。现代多用于决策、择吉与时空方位选择，尤以时家奇门最常用。',related:['bamen','jiuxing','bashen','jiugong']},
  {slug:'dunjia',name:'遁甲',pinyin:'Dùn Jiǎ',english:'Concealment of Jia',category:'qimen',shortDesc:'六甲元首遁藏于六仪之下，奇门立名之本。',detail:'遁甲是奇门遁甲立名之本：十天干中甲为至尊之首，如元帅主帅，不直接出现于九宫，而由六甲（甲子、甲戌、甲申、甲午、甲辰、甲寅）分别遁藏于戊己庚辛壬癸六仪之下，谓之遁甲。六甲为六旬之主帅，各领一旬，其所在之旬以遁仪为值符，统领全局。故起局布仪即布遁甲，寻值符即寻六甲所在。古人以甲为尊贵之神隐而不露，取象于用兵时主帅须深藏不露、护卫严密，此即遁甲之义。',related:['liujia','liuyi','xunshou','zhifu']},
  {slug:'sanqi-liuyi',name:'三奇六仪',pinyin:'Sān Qí Liù Yí',english:'Three Wonders and Six Instruments',category:'qimen',shortDesc:'乙丙丁三奇与戊己庚辛壬癸六仪，布局之根本。',detail:'三奇六仪是奇门遁甲布宫的核心要素：乙、丙、丁为三奇，戊、己、庚、辛、壬、癸为六仪，共九干，与九宫相配，遁去甲干正好一干一宫。三奇之中乙为日奇、丙为月奇、丁为星奇；六仪则各藏一甲，为六甲之护卫。起局布仪之法：阳遁顺布六仪、逆布三奇，阴遁逆布六仪、顺布三奇，从值符所遁之仪起按局数飞布九宫。三奇六仪落宫加临构成的天盘地盘组合，正是断事吉凶所依据的十干克应。',related:['sanqi','liuyi','liujia','dunjia']},
  {slug:'sanqi',name:'三奇',pinyin:'Sān Qí',english:'Three Wonders (Yi Bing Ding)',category:'qimen',shortDesc:'乙日奇丙月奇丁星奇，三奇临宫多主吉。',detail:'三奇指乙、丙、丁三干，是奇门遁甲中最受推崇的吉干：乙为日奇，象太阳之光；丙为月奇，象月亮之辉；丁为星奇，象星辰之明。奇门以得三奇为贵，三奇临吉门、吉星、吉神之宫，古人认为百事可为、谋为顺利；其中丁奇又称玉女，最灵最验。三奇亦可与八门、九星等组合成各种格局，如三奇得使、三奇入墓等。测事以用神临三奇为吉兆，惟须观其落宫旺衰与是否受制，方能定其吉凶深浅。',related:['yi-qi','bing-qi','ding-qi','sanqi-liuyi']},
  {slug:'liuyi',name:'六仪',pinyin:'Liù Yí',english:'Six Instruments (Wu Ji Geng Xin Ren Gui)',category:'qimen',shortDesc:'戊己庚辛壬癸六干，各藏一甲为甲之护卫。',detail:'六仪指戊、己、庚、辛、壬、癸六干，是奇门遁甲布宫的仪仗队伍，六甲元帅各遁于六仪之下，故有甲子戊、甲戌己、甲申庚、甲午辛、甲辰壬、甲寅癸之称。六仪在局中既是甲之藏身护卫，又承担天盘地盘的加临组合：天盘六仪加临地盘各干，构成十干克应中的诸多格局。六仪本无吉凶，须看其落宫旺衰、是否值符及与其他要素的生克关系，如值符临六仪主事有首领之象，六仪击刑则主暗中受损。',related:['sanqi-liuyi','liujia','wu-yi']},
  {slug:'liujia',name:'六甲',pinyin:'Liù Jiǎ',english:'Six Jia Leaders',category:'qimen',shortDesc:'甲子甲戌甲申甲午甲辰甲寅，六旬之主帅。',detail:'六指甲子、甲戌、甲申、甲午、甲辰、甲寅六个以甲为首的旬首，是六十甲子中六旬的主帅。奇门遁甲中甲为至尊不现于局，六甲各率一旬、各遁于一仪之下：甲子遁于戊、甲戌遁于己、甲申遁于庚、甲午遁于辛、甲辰遁于壬、甲寅遁于癸。起局之时，先看所测时辰属于何旬，找出旬首所遁之仪，即定该时值符之所起，故寻旬首、定值符为时家奇门起局第一要务。',related:['dunjia','xunshou','liuyi']},
  {slug:'xunshou',name:'旬首',pinyin:'Xún Shǒu',english:'Head of the Xun (Decade Cycle)',category:'qimen',shortDesc:'每旬之首的六甲，定值符值使之纲领。',detail:'旬首是六十甲子中每一旬的领队干支，即甲子、甲戌、甲申、甲午、甲辰、甲寅六甲（每旬十日，首日必为甲）。奇门起局时，先以时柱查其属何旬，该旬旬首所遁之仪即为本时辰的值符起点：如甲子旬中，戊为旬首之仪，遁于戊者当值。值符、值使皆由旬首推出，故有旬首为纲、值符为目之说。断事时值符所在宫即首领、贵人之象，看其旺衰生克可断全局吉凶所系。',related:['liujia','zhifu','zhishi']},
  {slug:'yi-qi',name:'乙奇',pinyin:'Yǐ Qí',english:'Yi Wonder (Day Wonder)',category:'qimen',shortDesc:'三奇之一，为日奇，象日光，主柔顺通达。',detail:'乙奇是三奇之一，乙木为阴柔之木，在奇门中为日奇，象太阳之光，为三奇中最柔顺的一奇。乙奇临宫，主事情婉转顺遂、宜以柔克刚，古人以为乙奇所临多主阴柔之力相助：测人主女人、医者，测事主经过周旋而能成就。乙奇与庚相合，而庚为阻隔之神，故乙奇又有制庚解阻之功。三奇之中乙奇性柔，最宜配合吉门使用；若落宫受制或入墓，则柔而无用，谋事难成。',related:['sanqi','sanqi-liuyi']},
  {slug:'bing-qi',name:'丙奇',pinyin:'Bǐng Qí',english:'Bing Wonder (Moon Wonder)',category:'qimen',shortDesc:'三奇之一，为月奇，象月辉，主威权光明。',detail:'丙奇是三奇之一，丙火为阳火，在奇门中为月奇，象月亮之辉，其性光明刚烈、声势赫赫。丙奇临宫，主事情公开明朗、进展有力，测事主有权威介入或得贵人声势之助；古人以丙为火精，能镇服邪晦，故有丙奇临宫百邪不侵之说。丙奇最喜生门、开门等吉门相配，成丙加戊飞鸟跌穴等吉格。惟丙火性烈，落宫受克或临死绝之地，则虚张声势、外强中干，须防急躁生变。',related:['sanqi','feiniao-diexue']},
  {slug:'ding-qi',name:'丁奇',pinyin:'Dīng Qí',english:'Ding Wonder (Star Wonder)',category:'qimen',shortDesc:'三奇之一，为星奇，又称玉女，最灵验。',detail:'丁奇是三奇之一，丁火为阴火，在奇门中为星奇，如星辰之光，古人又称之为玉女，为三奇中最灵验者。丁奇临宫，主事情有暗中助力、出奇制胜之妙，测事主文书、信息、女人或细腻之人事，测婚姻尤喜丁奇。丁奇主柔火而能照明，最宜与吉门同宫，断事逢丁多主有意外之喜或柳暗花明之机。丁奇若入墓受困或逢凶格，则星奇失灵，主文书阻滞、暗昧不明之事。',related:['sanqi','sanqi-rumu']},
  {slug:'wu-yi',name:'戊（甲子戊）',pinyin:'Wù (Jiǎ Zǐ Wù)',english:'Wu (Jiazi Wu)',category:'qimen',shortDesc:'六仪之首，甲子所遁，主钱财资本。',detail:'戊为六仪之首，五行属阳土，甲子旬之甲子遁于戊，故称甲子戊。奇门测事，戊为钱财、资本、关防之象：值符临戊或戊落旺宫，主财源有本、资金雄厚；测投资求财多观戊之落宫与生门的关系。戊为高山厚土，有镇守关隘之义，故亦主房产、土地、仓储之事。戊若入墓（落坤宫之类）或逢空亡，主资金困顿、谋财难成。六仪之中戊为首，逢甲子旬时即为旬首之仪，可作值符之用。',related:['liuyi','liujia','shengmen']},
  {slug:'ji-yi',name:'己（甲戌己）',pinyin:'Jǐ (Jiǎ Xū Jǐ)',english:'Ji (Jiaxu Ji)',category:'qimen',shortDesc:'六仪之一，甲戌所遁，主阴私田园之事。',detail:'己为六仪之一，五行属阴土，甲戌旬之甲戌遁于己，故称甲戌己。己为田园卑湿之土，性阴柔隐蔽，奇门测事以己为阴私、暗昧、坟墓田园之象：测人主心机深、好算计之人，测事主暗中谋划、不宜张扬之事。己土有容纳转化之功，亦有藏污纳垢之性，故逢己临宫，须防事有隐情。己与值符同宫或为旬首之仪时（甲戌旬），则暗昧之性转明，可作统领断事之用。',related:['liuyi','liujia']},
  {slug:'geng-yi',name:'庚（甲申庚）',pinyin:'Gēng (Jiǎ Shēn Gēng)',english:'Geng (Jiashen Geng)',category:'qimen',shortDesc:'六仪之一，甲申所遁，为阻隔之庚金。',detail:'庚为六仪之一，五行属阳金，甲申旬之甲申遁于庚，故称甲申庚。庚金为刀剑之金，刚健肃杀，奇门以庚为阻隔之神、为最凶之干：测事逢庚，主道路阻隔、事有障碍、竞争对抗，测行人主未归、测婚姻主分离之象。甲与庚为相克之敌，六甲遁形亦有避庚之意。制庚之法，以乙奇合庚或丙丁火克庚，故三奇临宫有解庚之功。庚亦主盗贼、兵戈、疾病之凶，须看其落宫生克而定轻重。',related:['liuyi','liujia','yi-qi']},
  {slug:'xin-yi',name:'辛（甲午辛）',pinyin:'Xīn (Jiǎ Wǔ Xīn)',english:'Xin (Jiawu Xin)',category:'qimen',shortDesc:'六仪之一，甲午所遁，主罪错变革之象。',detail:'辛为六仪之一，五行属阴金，甲午旬之甲午遁于辛，故称甲午辛。辛为珠玉首饰之金，质美而脆，奇门以辛为罪错、过失、变革之象：测事逢辛，主有差错、惩戒、革新之事，测人主性格刚锐而多咎。辛金本带贵气，落宫得生旺又逢吉门，反主以才能改过迁善、推陈出新。辛为旬首之仪时（甲午旬）可作值符断事。辛落宫逢冲克，主因小过而起大是非，须防口舌官非。',related:['liuyi','liujia']},
  {slug:'ren-yi',name:'壬（甲辰壬）',pinyin:'Rén (Jiǎ Chén Rén)',english:'Ren (Jiachen Ren)',category:'qimen',shortDesc:'六仪之一，甲辰所遁，主流动险陷之象。',detail:'壬为六仪之一，五行属阳水，甲辰旬之甲辰遁于壬，故称甲辰壬。壬为江河湖海之水，流动不息，奇门以壬为流动、奔波、险陷之象：测事逢壬，主事情多变、人来人往、行旅之事，测水灾、盗案亦以壬为用。壬水其势浩大，得时则主胸襟开阔、谋略过人；失令则泛滥成灾，主漂泊不定、事多反复。壬为旬首之仪时（甲辰旬）可作值符。壬与丁合，丁壬相见有阴阳交合之象，测婚喜亦有所主。',related:['liuyi','liujia']},
  {slug:'gui-yi',name:'癸（甲寅癸）',pinyin:'Guǐ (Jiǎ Yín Guǐ)',english:'Gui (Jiayin Gui)',category:'qimen',shortDesc:'六仪之一，甲寅所遁，主隐伏网罗之象。',detail:'癸为六仪之一，五行属阴水，甲寅旬之甲寅遁于癸，故称甲寅癸。癸为雨露之水，细小而渗透，奇门以癸为隐伏、阴邪、网罗之象：测事逢癸，主事情藏而不露、暗有罗网牵绊，测人主心思细密、善隐藏之人。癸水能润物亦能腐物，落宫得生旺，主以柔韧周旋成事；失令受克，则陷入罗网、难以脱身，故测囚狱、酒色、邪祟之事多观癸。癸为旬首之仪时（甲寅旬）可作值符断事。',related:['liuyi','liujia']},
  {slug:'jiugong',name:'九宫',pinyin:'Jiǔ Gōng',english:'Nine Palaces',category:'qimen',shortDesc:'洛书九宫为地盘骨架，奇门布局之基。',detail:'九宫即洛书九宫，是奇门遁甲布局的地盘骨架。洛书之数：戴九履一、左三右七、二四为肩、六八为足、五居中央，配后天八卦与干支，形成坎一、坤二、震三、巽四、中五、乾六、兑七、艮八、离九之序。奇门将三奇六仪、九星、八门、八神依次布于九宫：地盘九宫静而不动，天盘、人盘、神盘在其上运转。中五宫无专卦，其干与天禽星在转盘法中多寄于坤二宫。断事以用神落宫为纲，结合宫位五行生克论吉凶。',related:['sanpan','qimen-dunjia']},
  // ===== 奇门遁甲 · 八门 =====
  {slug:'bamen',name:'八门',pinyin:'Bā Mén',english:'Eight Gates',category:'qimen',shortDesc:'休生伤杜景死惊开，人盘之主，断事之枢。',detail:'八门是奇门遁甲人盘的核心要素，即休门、生门、伤门、杜门、景门、死门、惊门、开门，各配一宫一卦：休居坎、生居艮、伤居震、杜居巽、景居离、死居坤、惊居兑、开居乾。八门主人事，测事首看用神临何门：开、休、生为三吉门，主开创、安泰、生机；死、惊、伤为三凶门，主刑伤、惊恐、争斗；杜、景居中平，主闭塞与文书。八门随值使转动落宫，其与九宫的生克关系又生门迫、伏吟、反吟等格，为断吉凶之要。',related:['kaimen','shengmen','zhishi']},
  {slug:'xiumen',name:'休门',pinyin:'Xiū Mén',english:'Rest Gate',category:'qimen',shortDesc:'三吉门之一，居坎宫，主休养贵人相助。',detail:'休门是八门中的三吉门之一，居坎一宫，属水，正当冬季水旺之时，万物休息收藏，故名休门。休门主休养、安泰、和顺：测事临休门，主事情宜缓不宜急，得贵人相助、逢凶化吉，测婚姻主和合、测求财主平稳进益、测官讼主得贵人调停。休门亦主酒食宴乐之事，旺相之时百事可为。休门若落宫受制或逢凶格，则休养之利不显，须防安逸懈怠、事有迟延。古人云休门出入百事昌，为择吉常用之门。',related:['bamen','shengmen','kaimen']},
  {slug:'shengmen',name:'生门',pinyin:'Shēng Mén',english:'Life Gate',category:'qimen',shortDesc:'三吉门之首，居艮宫，主生机财源。',detail:'生门是八门中吉气最盛之门，居艮八宫，属土，正当冬春之交万物萌生之时，故名生门。生门主生长、生机、财源：测求财、置业、经商、上任，临生门多主大利，古人谓生门最利求财谋事，百事皆宜。生门旺相之时，主财源广进、事业兴盛；测病逢生门亦主生机有望。惟生门落宫受克或逢空亡、凶格，则财源受阻，须防盛极而衰。生门与戊同看，为测财之要门，用神临之多为吉断。',related:['bamen','wu-yi','xiumen']},
  {slug:'shangmen',name:'伤门',pinyin:'Shāng Mén',english:'Injury Gate',category:'qimen',shortDesc:'凶门之一，居震宫，主损伤争斗捕猎。',detail:'伤门是八门中的凶门之一，居震三宫，属木，正当春分万物勃发、竞争激烈之时，故主伤损。伤门主伤害、争斗、竞争、捕猎：测事临伤门，主有损伤、破财、官非争斗之象，出行须防车祸跌伤。然伤门亦有其用：古人谓捕捉走兽、讨债索物、渔猎之事反宜伤门，因其主动而有杀伤之力。伤门旺相有制，主以竞争手段得胜；若落宫受克逢凶，则伤上加伤。测病临伤门，主外伤或肝胆之疾。',related:['bamen','simen','jing-men']},
  {slug:'dumen',name:'杜门',pinyin:'Dù Mén',english:'Blocking Gate',category:'qimen',shortDesc:'中平之门，居巽宫，主闭塞隐匿防守。',detail:'杜门是八门中的中平之门，居巽四宫，属木，正当春夏之交草木繁茂、闭塞不通之时，故名杜门。杜门主闭塞、隐匿、防守：测事临杜门，主事情受阻不通、不宜张扬，宜守不宜攻；测逃亡主藏匿难寻，测官司主口舌闭塞难伸。然杜门亦有可用之处：古人谓隐匿躲藏、筑堤防水、防奸细、保密之事宜杜门，因其主封闭隐藏。杜门旺相有制，主以静制动、保守成事；若逢凶格则闭塞不通，谋为费力。',related:['bamen','jingmen','jing-men']},
  {slug:'jingmen',name:'景门',pinyin:'Jǐng Mén',english:'Scenery Gate',category:'qimen',shortDesc:'中平之门，居离宫，主文书光明虚华。',detail:'景门是八门中的中平之门，居离九宫，属火，正当夏日炎炎、万物华彩之时，故主景光明丽。景门主文书、信息、光明之象，亦主血光与虚华：测考试、上书、献策、文书之事临景门为吉，主文采得显；测其他事则主来势热闹而结果虚浮，须防华而不实。景门属火，旺相之时主声名远播、门庭若市；落宫受克逢凶，则文书生非、因虚名惹祸。测病临景门，须防心脑血管、眼目之火症。',related:['bamen','kaimen']},
  {slug:'simen',name:'死门',pinyin:'Sǐ Mén',english:'Death Gate',category:'qimen',shortDesc:'大凶之门，居坤宫，主刑伤丧葬之事。',detail:'死门是八门中的大凶之门，居坤二宫，属土，正当秋收万物肃杀之时，生气已绝，故主死亡、刑伤。死门主丧葬、吊唁、刑戮之事：测事临死门，多主事情绝望、生机渺茫，出行、谋事、求财皆所忌。然古人谓吊丧送葬、刑戮除奸、猎捕猛兽之事反宜死门。死门旺相受制，凶性可减；落宫逢生旺又逢凶格，则大凶，主重病难愈、事败难成。测病临死门最忌，须防危殆；惟其土性，亦主田土坟墓之事。',related:['bamen','shangmen']},
  {slug:'jing-men',name:'惊门',pinyin:'Jīng Mén',english:'Shock Gate',category:'qimen',shortDesc:'凶门之一，居兑宫，主惊恐口舌官非。',detail:'惊门是八门中的凶门之一，居兑七宫，属金，正当秋分金气肃杀之时，草木凋零、令人惊惧，故主惊恐。惊门主惊恐、口舌、官非、诉讼：测事临惊门，主事有虚惊、口舌是非、争执官讼之象，出行防惊险，经商防破财惹讼。然惊门属金，有决断言辞之力，古人谓捕捉逃犯、斗讼辩论之事亦有用其之时。惊门旺相有制，主以言词取胜；落宫受克逢凶，则惊恐成实、是非缠身。测病临惊门，须防惊悸不安之症。',related:['bamen','jingmen','simen']},
  {slug:'kaimen',name:'开门',pinyin:'Kāi Mén',english:'Opening Gate',category:'qimen',shortDesc:'三吉门之一，居乾宫，主开创官运事业。',detail:'开门是八门中的大吉之门，居乾六宫，属金，乾为天、为君，秋金肃杀中有开创之义，故主通达开创。开门主事业、官运、开业、出行：测求官、上任、开业、谋事临开门，主前程通达、百事可为，古人谓开门出入最利求名求利。开门亦主公开、明朗，测诉讼主得理，测出行主顺利。开门旺相之时，主事业兴盛、贵人相助；若落宫受制或逢凶格，则开创受阻，须防好事多磨。开门与值符同宫，多为大吉之象。',related:['bamen','xiumen','shengmen']},
  // ===== 奇门遁甲 · 九星 =====
  {slug:'jiuxing',name:'九星',pinyin:'Jiǔ Xīng',english:'Nine Stars',category:'qimen',shortDesc:'天蓬任冲辅英芮柱心禽九星，天盘之主。',detail:'九星是奇门遁甲天盘的核心要素，指天蓬、天任、天冲、天辅、天英、天芮、天柱、天心、天禽九星，各配一宫：蓬居坎、任居艮、冲居震、辅居巽、英居离、芮居坤、柱居兑、心居乾，天禽居中五宫，转盘法中多寄于坤二。九星有吉凶之分，大要以天辅、天心为吉，天蓬、天芮为凶，余星依旺相休囚而论。九星随值符转动加临各宫，测事以用神所乘之星断其性质，如天芮主病、天心主医。九星之吉凶须合旺衰观之。',related:['tianpeng-xing','tianfu-xing-qm','tianxin-xing']},
  {slug:'tianpeng-xing',name:'天蓬星',pinyin:'Tiān Péng Xīng',english:'Tian Peng Star (Water Bandit Star)',category:'qimen',shortDesc:'九星之一，居坎宫属水，大凶之星。',detail:'天蓬星是九星之一，居坎一宫，五行属水，正当冬季，为九星中著名的凶星。天蓬主盗贼、暗昧、阴险之事：测事乘天蓬，主有盗失、欺诈、奸邪之象，故古称盗星；测盗贼、捕亡即以天蓬为用神。然天蓬属水主智，旺相之时亦主智谋深沉、应变有术，为将者用奇谋亦常乘蓬。天蓬若临吉门吉格、落宫旺相，凶性可减，反主以智成事；落宫受克逢凶，则主盗贼官非、行踪不测。',related:['jiuxing','kan-trigram']},
  {slug:'tianren-xing',name:'天任星',pinyin:'Tiān Rèn Xīng',english:'Tian Ren Star (Responsibility Star)',category:'qimen',shortDesc:'九星之一，居艮宫属土，吉星主厚德。',detail:'天任星是九星之一，居艮八宫，五行属土，艮为山，有厚重敦实之象，为吉星。天任主担当、任重、厚德：测事乘天任，主事情有可托付之人，宜承担重任、守成立业，测人主忠厚可靠、任劳任怨。天任临吉门旺相，主名利有份、事业稳固；若落宫受制，则任重而力薄，须防独力难支。天任土性主田土房产之事，测置产、迁居亦多观任星。九星之中天任为吉，宜静守积累，不宜轻举妄动。',related:['jiuxing','gen-trigram']},
  {slug:'tianchong-xing',name:'天冲星',pinyin:'Tiān Chōng Xīng',english:'Tian Chong Star (Assault Star)',category:'qimen',shortDesc:'九星之一，居震宫属木，主勇武突击。',detail:'天冲星是九星之一，居震三宫，五行属木，震为雷，有奋发震动之象，为次吉之星。天冲主勇武、冲击、行动：测事乘天冲，主事情进展迅速、有冲劲，宜主动出击、不宜坐守；古人行军、诉讼、竞争之事多喜天冲，因其有勇往直前之力。天冲临吉门旺相，主以魄力成事、名震一方；落宫受克逢凶，则冲动生祸，须防鲁莽招灾。天冲亦主车辆、震动、奔波之事，测出行乘之，利在迅速。',related:['jiuxing','zhen-trigram']},
  {slug:'tianfu-xing-qm',name:'天辅星',pinyin:'Tiān Fǔ Xīng',english:'Tian Fu Star (Assist Star)',category:'qimen',shortDesc:'九星之一，居巽宫属木，大吉文星。',detail:'天辅星是九星中的大吉之星，居巽四宫，五行属木，巽为风为入，有教化辅佐之象。天辅主文教、辅佐、仁慈：测学业、考试、文书之事乘天辅最吉，主文思通达、得人辅导；测事主有贵人辅佐、谋为顺遂。天辅为九星中最利读书求学之星，古人出行、上任、求名皆喜天辅临宫。天辅临吉门旺相，主文名远播、仕途顺利；若落宫受制，则文星失力，须防谋事缺辅。天辅本属巽木，测风、绳索、商业之事亦有所主。',related:['jiuxing','xun-trigram']},
  {slug:'tianying-xing',name:'天英星',pinyin:'Tiān Yīng Xīng',english:'Tian Ying Star (Heroic Star)',category:'qimen',shortDesc:'九星之一，居离宫属火，主文明血光。',detail:'天英星是九星之一，居离九宫，五行属火，离为火为明，其性热烈焕发，为平中之星。天英主文明、英华、光明之象，亦主血光与虚华：测事乘天英，主事有声势、门面光鲜，惟须防盛气凌人、外实内虚。测文化、文书、演艺之事，天英得地主才华显露；测其他事则主虚张声势。天英属火，旺相之时主声名扬于外；落宫受克逢凶，主火症、血光、口舌之争。古人以天英为荧惑之星，出师须防其火光之灾。',related:['jiuxing','li-trigram']},
  {slug:'tianrui-xing',name:'天芮星',pinyin:'Tiān Ruì Xīng',english:'Tian Rui Star (Sickness Star)',category:'qimen',shortDesc:'九星之一，居坤宫属土，病星大凶。',detail:'天芮星是九星之一，居坤二宫，五行属土，坤为地，其性阴晦，为著名的病星、凶星。天芮主疾病、阴邪、滞碍：测病即以天芮为用神，看其落宫旺衰及所乘门神，以断病之轻重与所主脏腑；测事乘天芮，主有隐患、病人、灾厄纠缠之事。天芮虽凶，若落宫旺相、临吉门吉格，亦主病有医可治、事有化解；坤为地，天芮亦主田土、老妇之事。古人出兵避天芮，因其有死丧疾病之气。',related:['jiuxing','kun-trigram','tianxin-xing']},
  {slug:'tianzhu-xing',name:'天柱星',pinyin:'Tiān Zhù Xīng',english:'Tian Zhu Star (Pillar Star)',category:'qimen',shortDesc:'九星之一，居兑宫属金，主口舌破坏。',detail:'天柱星是九星之一，居兑七宫，五行属金，兑为泽为口，其性肃杀破败，为凶星。天柱主口舌、破坏、毁折：测事乘天柱，主有口舌是非、事被破坏之象，宜防小人中伤；测诉讼乘天柱，主以言辞争胜或官非破耗。然天柱属金主断，旺相之时亦主果决有力、能当一面，古人谓柱石之材。天柱临吉门旺相，凶性可减，主以口才成事；落宫受克逢凶，主破败口舌、金刃之伤。测病乘天柱，须防肺疾喉症。',related:['jiuxing','dui-trigram']},
  {slug:'tianxin-xing',name:'天心星',pinyin:'Tiān Xīn Xīng',english:'Tian Xin Star (Heart Star)',category:'qimen',shortDesc:'九星之一，居乾宫属金，大吉医星。',detail:'天心星是九星中的大吉之星，居乾六宫，五行属金，乾为天为君，其性刚健仁爱，为医星。天心主医药、救治、谋略：测病以天心为医星，乘天心主得良医、病有转机；测事乘天心，主有贵人相助、谋为有成，尤利求医问药、筹划大局之事。天心为九星中最吉者之一，临吉门旺相，主诸事顺遂、逢凶化吉；若落宫受制，则医力不足，须防延误。天心属金，亦主金融、器械、果断决策之事，古人上任、出行皆喜之。',related:['jiuxing','qian-trigram','tianrui-xing']},
  {slug:'tianqin-xing',name:'天禽星',pinyin:'Tiān Qín Xīng',english:'Tian Qin Star (Center Star)',category:'qimen',shortDesc:'九星之一，居中五宫属土，寄坤二宫。',detail:'天禽星是九星之一，居中五宫，五行属土，位居中央，统摄八方，为大吉之星。天禽主中正、统御、厚德：古人以禽星居中得正气，其性端庄，测事乘天禽，主得中正之道、有统御之象，宜守中致和。天禽居中五宫无专卦可寄，转盘法中多寄于坤二宫与天芮同处，故断事须视其寄宫之旺衰。天禽临吉门旺相，主为人正直、谋为有成；落宫受制则中气不足，须防失其主心骨。天禽属土，亦主田土、中央之事。',related:['jiuxing','tianrui-xing']},
  // ===== 奇门遁甲 · 八神 =====
  {slug:'bashen',name:'八神',pinyin:'Bā Shén',english:'Eight Spirits',category:'qimen',shortDesc:'值符螣蛇太阴六合白虎玄武九地九天。',detail:'八神是奇门遁甲神盘的核心要素，即值符、螣蛇、太阴、六合、白虎、玄武、九地、九天（有版本以勾陈、朱雀代白虎、玄武）。八神为虚神，主吉凶之气：值符为八神之首主贵人统领，螣蛇主虚惊怪异，太阴主暗中谋助，六合主和合交易，白虎主凶丧刀兵，玄武主盗贼暧昧，九地主伏藏稳固，九天主高远张扬。八神随值符落宫，阳遁顺行、阴遁逆布。断事以用神所乘之神参断吉凶深浅，神煞之力须合门星宫参看。',related:['zhifu','liuhe-shen','baihu-shen']},
  {slug:'tengshe',name:'螣蛇',pinyin:'Téng Shé',english:'Teng She (Flying Snake)',category:'qimen',shortDesc:'八神之一，主虚惊怪异、缠绕反复。',detail:'螣蛇是八神之一，居八神第二位，其性虚诈诡异，主虚惊、怪异、缠绕之事。测事乘螣蛇，主事情虚而不实、多有惊吓与怪诞之象，如测梦兆、怪异之事以螣蛇为用；测人事则主有谎言欺骗、纠缠不清之处，须防小人作祟。螣蛇亦有灵异之性，古人测鬼神、怪异、梦魇之事多观螣蛇。螣蛇临吉门旺相，主以计谋周旋、虚惊一场；落宫受制逢凶，则缠绕难脱、惊疑成实。测病乘螣蛇，须防神经衰弱、惊悸之症。',related:['bashen','xuanwu-shen']},
  {slug:'taiyin-shen',name:'太阴（八神）',pinyin:'Tài Yīn',english:'Tai Yin (Spirit of Subtle Help)',category:'qimen',shortDesc:'八神之一，主暗中相助、谋略阴私。',detail:'太阴是八神之一，其性阴柔潜藏，主暗中相助、谋略与阴私之事。测事乘太阴，主有暗中之助、幕后策划之力，宜秘密行事、不宜张扬；古人以婚姻、财运乘太阴为吉，主得女性或暗中贵人助力。太阴临吉门旺相，主以柔制胜、谋事可成；若落宫受制逢凶，则阴私过度，主暗昧不明、阴谋害己。太阴与文曲、妇女、财产之事相应，测家宅乘太阴，主家中内助得力；惟须防其阴柔过甚，反生忧疑。',related:['bashen','jiudi-shen']},
  {slug:'liuhe-shen',name:'六合（八神）',pinyin:'Liù Hé',english:'Liu He (Spirit of Harmony)',category:'qimen',shortDesc:'八神之一，主和合、婚姻、交易之事。',detail:'六合是八神之一，其性和合圆满，主合作、婚姻、交易、喜庆之事。测婚姻、合伙、签约之事乘六合为大吉，主两情相悦、和气生财、双方有诚意；测其他事亦主得人和之助。六合临吉门旺相，主和合之事顺遂有成；若落宫受制逢凶，则表面和气、内藏不合，或婚约、合同有变。六合主中介、牵线之人，测介绍撮合之事以六合为用神。六合与太阴同看，主暗中亦有和合之力；古人出行、会友皆喜乘六合。',related:['bashen','taiyin-shen']},
  {slug:'baihu-shen',name:'白虎（八神）',pinyin:'Bái Hǔ',english:'Bai Hu (White Tiger)',category:'qimen',shortDesc:'八神之一，大凶神，主凶丧刀兵血光。',detail:'白虎是八神中的大凶之神，其性刚暴肃杀，主凶丧、刀兵、血光、争斗之事。测事乘白虎，主有灾伤、破财、官非、病患之象，出行须防车祸刑伤，测病须防急症血光。然白虎亦有威猛之正面：古人用兵、捕猎、除奸之事反宜白虎，因其有杀伐镇服之力。白虎临吉门旺相有制，主以威严成事、化险为夷；落宫受制逢凶，则凶灾难免。测孝服丧事以白虎为用，乘之而旺相，亦主因武职、竞争而显。',related:['bashen','jing-men']},
  {slug:'xuanwu-shen',name:'玄武（八神）',pinyin:'Xuán Wǔ',english:'Xuan Wu (Black Tortoise)',category:'qimen',shortDesc:'八神之一，主盗贼、失脱、暧昧之事。',detail:'玄武是八神之一，其性暗昧窃取，主盗贼、失脱、欺骗、暧昧之事。测失物、防盗之事以玄武为用神：乘玄武主有失窃之虞或财物被骗；测人则主心术不正、暗藏奸诈之人。玄武亦主男女暧昧、隐私之事，测婚姻乘玄武须防感情不实。玄武临吉门旺相，凶性可减，主以智取胜或事有隐情不碍大局；落宫受制逢凶，主失脱成真、名誉受损。玄武属水，测酒色、口舌、文书伪造之事亦多观之。',related:['bashen','tengshe']},
  {slug:'jiudi-shen',name:'九地（八神）',pinyin:'Jiǔ Dì',english:'Jiu Di (Nine Earths)',category:'qimen',shortDesc:'八神之一，主伏藏、稳固、安静之事。',detail:'九地是八神之一，其性坤厚安静，主伏藏、稳固、防守之事。测事乘九地，主事情宜守不宜攻、宜静不宜动，古人谓埋伏、藏兵、固守、迁坟安葬之事乘九地为吉，因其主深藏不露。九地临吉门旺相，主根基稳固、以静制动、后发制人；若落宫受制逢凶，则沉滞难发，主事久拖不决。测人乘九地，主性格沉稳、不善张扬。九地为地气之极，测风水、阴宅之事亦以九地为用神；惟凡事乘九地，进展较缓。',related:['bashen','jiutian-shen']},
  {slug:'jiutian-shen',name:'九天（八神）',pinyin:'Jiǔ Tiān',english:'Jiu Tian (Nine Heavens)',category:'qimen',shortDesc:'八神之一，主高远、张扬、宜动宜进。',detail:'九天是八神之一，其性刚健高亢，主高远、张扬、进取之事。测事乘九天，主事情格局宏大、宜主动进取，古人谓出兵、远行、上书、上任乘九天为吉，因其有飞腾高举之力；九天亦主望高远之事，测出行利远行高就。九天临吉门旺相，主一举成名、志得意满；若落宫受制逢凶，则好高骛远、虚张声势。测人乘九天，主志向远大、不甘人后。九天为天极之象，测天气、前程、宗教之事亦多观之。',related:['bashen','jiudi-shen']},
  {slug:'zhifu',name:'值符',pinyin:'Zhí Fú',english:'Zhi Fu (Duty Talisman)',category:'qimen',shortDesc:'当值之符，统领全局，为八神之首。',detail:'值符是奇门遁甲中最紧要的纲领，含义有二：一为旬首所遁之仪当其值，即本时辰的值符（星），统领全局；二为八神之首的值符神，主贵人、首领之象。时家奇门起局，先寻旬首定值符，转盘法中值符星随时干加临于天盘，八神之值符随其落宫。断事以值符为天乙贵人：测事乘值符，主有贵人相助、事有主心骨，谋为多顺；值符落宫旺相，全局有统摄之象；受制逢凶，则群龙无首、事难主持。',related:['xunshou','zhishi','bashen']},
  {slug:'zhishi',name:'值使',pinyin:'Zhí Shǐ',english:'Zhi Shi (Duty Envoy)',category:'qimen',shortDesc:'与值符同源的值班之门，主事之执行。',detail:'值使是奇门遁甲中与值符并称的纲领：值符为当值之星神，值使则为当值之门，二者皆由旬首推出。起局之时，旬首所遁之仪落于某宫，该宫原辖之门即为值使；转盘法中值使门随其运转加临各宫，主事情的执行与人事的具体动向。断事时值符主谋、主贵人，值使主行、主过程：看值使之落宫与旺衰，可断事情由何人何事推动、何时可成。值使临吉门旺相，主执行有力、事有结果；逢凶则半途而废。',related:['zhifu','xunshou','bamen']},
  {slug:'sanpan',name:'三盘',pinyin:'Sān Pán',english:'Three Plates (Tian Ren Di)',category:'qimen',shortDesc:'天盘九星、人盘八门、地盘九宫之总称。',detail:'三盘指奇门遁甲起局后层层叠加的三层结构：地盘为九宫八卦，静而不动，承载干支与宫位之象；人盘为八门，随值使运转，主人事动静；天盘为九星，随值符运转，兼载天盘三奇六仪，主天时大势。断事时三层合参：天盘看大势外因，人盘看人事过程，地盘看根基环境，另有八神居最上层主吉凶之气。天地人三盘相配，宫生门、门生星则层层相生为吉，相克则层层受阻为凶。三盘之学为奇门断事之根本。',related:['jiugong','jiuxing','bamen']},
  {slug:'yangdun',name:'阳遁',pinyin:'Yáng Dùn',english:'Yang Dun (Yang Concealment)',category:'qimen',shortDesc:'冬至后夏至前用阳遁，顺布六仪逆布三奇。',detail:'阳遁是奇门遁甲按节气分阴阳的两种起局法之一：从冬至到夏至之间，阳气上升，用阳遁。阳遁起局时顺布六仪、逆布三奇，即六仪按局数从值符宫起顺飞九宫，三奇则逆行布列。阳遁共一至九局，局数由节气与日干支（上中下三元）决定，如冬至、惊蛰用一七四局等。阳遁之时阳气用事，古人谓阳遁利主动、进取、明朗之事，测事乘阳遁之局，事情进展较快、较公开。阳遁与阴遁合观，断事之动静刚柔以此为纲。',related:['yindun','jieqi-dingju','qimen-dunjia']},
  {slug:'yindun',name:'阴遁',pinyin:'Yīn Dùn',english:'Yin Dun (Yin Concealment)',category:'qimen',shortDesc:'夏至后冬至前用阴遁，逆布六仪顺布三奇。',detail:'阴遁是奇门遁甲两种起局法之一：从夏至到冬至之间，阴气渐盛，用阴遁。阴遁起局时逆布六仪、顺布三奇，即六仪从值符宫起逆飞九宫，三奇则顺行布列，与阳遁恰相反。阴遁亦有一至九局，局数依节气三元而定。阴遁之时阴气用事，古人谓阴遁利守静、隐秘、暗行之事：测事乘阴遁之局，事情发展较缓、较为隐蔽，宜暗中筹划。断事须先分清局之阴阳，再看主客动静，方能定进退趋避之宜。',related:['yangdun','jieqi-dingju','qimen-dunjia']},
  // ===== 奇门遁甲 · 历法起局 =====
  {slug:'chaoshen-jieqi',name:'超神接气',pinyin:'Chāo Shén Jiē Qì',english:'Chao Shen Jie Qi (Calendar Alignment)',category:'qimen',shortDesc:'符头与节气的先后差，起局历法关键。',detail:'超神接气是奇门遁甲历法中处理符头与节气关系的术语。奇门以五日为一元，甲、己二日称符头，一个节气分上中下三元；按常理节气的交节时刻应恰逢符头，但干支历与节气实历并不同步，便出现先后之差：符头先于交节时刻到来，谓之超神；节气已到而符头未至，谓之接气。超神与接气之差积累到一定程度，就会使局数与节气错乱，故须以置闰或拆补之法调整，使奇门三元重新与节气相合，此为起局历法的关键。',related:['zhirun','chaibu','jieqi-dingju']},
  {slug:'zhirun',name:'置闰',pinyin:'Zhì Rùn',english:'Zhi Run (Intercalary Adjustment)',category:'qimen',shortDesc:'以加设闰局调和符头与节气的古法。',detail:'置闰是奇门遁甲调整历法的传统方法：当超神接气产生的差数积累到一定程度（古人以超神超过一定时日为限），便人为加设一整个节气之局，称为置闰。古法置闰多在芒种、大雪两节气前后（阴阳遁将转换之时）进行，以甲己符头为准则：把该节气上中下三元重新完整地续排一遍，使后续三元与节气恢复对应。置闰为古传正法，讲究节气与符头两相合；因推算繁复，近代亦有以拆补法代替者，两派并行，学者须先明其理。',related:['chaoshen-jieqi','chaibu','jieqi-dingju']},
  {slug:'chaibu',name:'拆补',pinyin:'Chāi Bǔ',english:'Chai Bu (Split and Patch Method)',category:'qimen',shortDesc:'以交节时刻拆开三元直接补续的起局法。',detail:'拆补是近代流行的奇门起局法，与置闰相对：不论符头与节气谁先谁后，一律以交节时刻为界，将所在的旬日一分为二，交节前仍用上一节气之局，交节后立即改用新节气之局，谓之以交节拆开、以符头补续。拆补法无需置闰，排局简便、应时准确，主张局随节气走，故现代时家奇门多采用。惟拆补法所成之局，一元可能不足五日或略超五日，与古法置闰所排之局偶有差异，门派间各执一说，习者宜择师而从。',related:['zhirun','chaoshen-jieqi','jieqi-dingju']},
  {slug:'jieqi-dingju',name:'节气定局',pinyin:'Jié Qì Dìng Jú',english:'Solar Term Chart Determination',category:'qimen',shortDesc:'按节气与日干支三元定阴阳遁局数之法。',detail:'节气定局是奇门遁甲确定局数的基本法则：先以节气定阴阳遁（冬至后阳遁、夏至后阴遁），再以日干支查符头定上中下三元，最后依歌诀定局数。定局歌诀如：冬至、惊蛰一七四，小寒二八五，大寒、春分三九六，立春八五二，雨水九六三，清明、立夏四一七，谷雨、小满五二八，芒种六三九（阳遁）；夏至、白露九三六等（阴遁）。歌中数字即上元、中元、下元所用局数，如冬至后上元用阳遁一局、中元七局、下元四局。',related:['yangdun','yindun','shijia-qimen']},
  {slug:'shijia-qimen',name:'时家奇门',pinyin:'Shí Jiā Qí Mén',english:'Hour-Based Qi Men',category:'qimen',shortDesc:'以时辰起局的奇门，最常用最灵验。',detail:'时家奇门是以时辰为基本起局单位的奇门遁甲，一日十二时辰，五日六十时辰成一甲子，恰合一元（五日）之数，故时家奇门与三元历法相配最密。起局以时柱干支寻旬首、定值符值使，逐时布三奇六仪与星门神，测事最细最灵，是奇门诸家（年家、月家、日家、时家）中最常用者。古人有年吉不如月吉、月吉不如日吉、日吉不如时吉之说，时家奇门因应机而断、刻刻不同，最宜用于决策、出行、谈判等具体人事的择时与预测。',related:['jieqi-dingju','rijia-qimen','zhifu']},
  {slug:'rijia-qimen',name:'日家奇门',pinyin:'Rì Jiā Qí Mén',english:'Day-Based Qi Men',category:'qimen',shortDesc:'以日干支起局，主一日吉凶与方位择吉。',detail:'日家奇门是以日干支为起局基础的奇门遁甲，专用于择日与断一日之吉凶。它与时家奇门不同：日家不逐时起局，而以日为主布八门九星，配合十二黄黑道等法则，断当日宜忌与吉方，用于嫁娶、出行、开市、上任等择日之事，简便实用。日家之法与黄历择日相表里，民间流传较广。古传奇门尚有年家、月家之说，皆以更粗的时间单位起局，惟以时家断事最精、日家择日用事最便，二者常相配合使用。',related:['shijia-qimen','jieqi-dingju','bamen']},
  {slug:'zhuanpan-qimen',name:'转盘奇门',pinyin:'Zhuàn Pán Qí Mén',english:'Rotating Plate Qi Men',category:'qimen',shortDesc:'天盘人盘旋转加临的奇门主流流派。',detail:'转盘奇门是奇门遁甲的主流流派，以其星门依转动方式加临而得名：地盘九宫静定，天盘（九星及天盘三奇六仪）随值符转动加临于地盘之上，人盘八门随值使转动，八神随值符落宫。转盘法保留了奇门最古老的天盘转、地盘静之象，布局以旬首定值符、值符加时干、值使加时支，断事重星门神仪的组合克应，十干克应即以此派口诀为宗。民间流传的奇门大多属转盘一派，习者最众。',related:['feipan-qimen','zhifu','zhishi']},
  {slug:'feipan-qimen',name:'飞盘奇门',pinyin:'Fēi Pán Qí Mén',english:'Flying Plate Qi Men',category:'qimen',shortDesc:'星门依九宫轨迹飞布，与转盘相对。',detail:'飞盘奇门是奇门遁甲的重要流派，与转盘奇门相对：不以旋转加临，而以洛书九宫的飞布轨迹（如二四为肩、六八为足之序）将九星、八门依次飞布九宫，故称飞盘或飞宫。飞盘法在处理中五宫、寄宫及星门排列上与转盘颇有出入，布局口诀自成体系，古称飞宫奇门。飞盘奇门因飞布规则严密、层次分明，在断应期与精细断事上有独到之处，与转盘并称两大派。学者须先明转盘再参飞盘，二者不可混排，以免星门错位。',related:['zhuanpan-qimen','jiugong','jiuxing']},
  {slug:'yinpan-qimen',name:'阴盘奇门',pinyin:'Yīn Pán Qí Mén',english:'Yin Plate Qi Men',category:'qimen',shortDesc:'道家传承的奇门流派，重象意直读。',detail:'阴盘奇门是近代兴起并流行的一种奇门流派，多传自道家，与传统的阳盘转盘、飞盘法在起局与断法上有别：起局不论阴阳遁皆以当下时空直接起局，布盘亦有其独特之处；断事不重死板的格局歌诀，而重宫、星、门、神、干所成象意的直接解读，讲究观象直断、见象说事。阴盘奇门因其起局简捷、断语生动具体而广为流行，惟其口诀流派纷杂、传承各异，与传统奇门在定局原则上存在争论。学者宜先立传统根基，再酌情参研。',related:['zhuanpan-qimen','feipan-qimen','sanpan']},
  // ===== 奇门遁甲 · 断法格局 =====
  {slug:'keying',name:'克应',pinyin:'Kè Yìng',english:'Ke Ying (Correspondence of Omens)',category:'qimen',shortDesc:'局象预示的应验之象，断事吉凶所本。',detail:'克应是奇门遁甲断事的重要概念，指局中各种组合所预示的吉凶应验之象，亦称应候。其来源有三：一是十干克应，即天盘干加临地盘干所产生的种种吉凶组合，如戊加丙青龙返首之类；二是八门九星加临各宫后的克应断语，如门迫、门制之应；三是时辰、方位上的动应，即所测之事发生的时间方位之象。断事观用神所乘之星门神仪，查其克应吉凶，再以马星、旬空、冲合等断应期。克应之学为奇门实战的精髓所在。',related:['shigan-keying','qimen-yongshen','fuyin']},
  {slug:'fuyin',name:'伏吟',pinyin:'Fú Yín',english:'Fu Yin (Lying Down Chant)',category:'qimen',shortDesc:'星门伏于本宫不动，主静守迟滞之象。',detail:'伏吟是奇门遁甲的两种基本局态之一，指九星、八门落回其本宫不动，或天盘干与地盘干相同（如戊加戊之类），如人伏地呻吟，故名伏吟。伏吟之局主伏、主静、主迟缓：测事逢伏吟，主事情进展缓慢、宜守不宜动，谋事难以速成，出行主滞留；古人谓伏吟之局诸事主迟，宜静守待时。然伏吟亦有可用：利于固守、埋伏、收藏、静养之事。伏吟逢旺相有吉门，主以静制动；逢凶煞，则事多停滞、抑郁难伸。',related:['fanyin','zhifu','menpo']},
  {slug:'fanyin',name:'反吟',pinyin:'Fǎn Yín',english:'Fan Yin (Reversed Chant)',category:'qimen',shortDesc:'星门落于对冲之宫，主反复变动之象。',detail:'反吟是奇门遁甲的两种基本局态之一，与伏吟相对，指九星、八门落于本宫相对冲之宫（如天心落震、开门落巽之类），或天盘干与地盘干相冲，故名反吟。反吟之局主反、主动、主变：测事逢反吟，主事情反复无常、先成后败或先败后成，远行主中途折返，测病主反复发作；古人谓反吟主事有反复、宜防突变。然反吟亦有可用：利于散财、变革、解围脱困之事，动而求变反有转机。反吟逢吉门旺相，主动中取利；逢凶煞则反复招灾。',related:['fuyin','menpo']},
  {slug:'menpo',name:'门迫',pinyin:'Mén Pò',english:'Men Po (Gate Oppressed)',category:'qimen',shortDesc:'八门与九宫五行相克，主事受制约。',detail:'门迫是奇门遁甲断事的凶象之一，指八门落宫后与九宫五行相克的情形：门克所落之宫，或宫克所落之门，皆谓门迫（古法细分有门迫、门制之说，各派口径略异），如属金的开门、惊门落于属木的震巽之宫，木门的伤门、杜门落于属土的坤艮之宫之类。门迫之象主事情受外在制约、横生障碍：测事逢门迫，主谋为受阻、好事难成，吉门逢迫亦减其吉。断门迫须合观旺衰，门旺迫宫为门胜，宫旺迫门则事更艰难。',related:['bamen','jiugong','fuyin']},
  {slug:'maxing',name:'马星',pinyin:'Mǎ Xīng',english:'Horse Star (Yi Ma)',category:'qimen',shortDesc:'驿马星，主动象与应期，断事之钥。',detail:'马星即驿马，是奇门遁甲断应期与动象的重要参考。驿马以日支或时支按三合局求之：申子辰日马在寅，寅午戌日马在申，巳酉丑日马在亥，亥卯未日马在巳。马星主奔驰、变动、外出：局中马星所临之宫受冲合之时，常为事情发动或应验之期；用神乘马，主事有走动、出行、调动之象，测行人归来、消息到来亦看马星。马星逢空亡则马失其力，主空跑一趟；马星逢冲，主变动加快。断应期以马星为最常用之钥。',related:['xunkong','qimen-yongshen']},
  {slug:'xunkong',name:'旬空',pinyin:'Xún Kōng',english:'Xun Kong (Void of the Decade)',category:'qimen',shortDesc:'六甲旬中空亡二支，主虚象与应期。',detail:'旬空又称空亡，是奇门遁甲断虚实与应期的重要概念：每旬十日，天干尽而地支余二，此二支即该旬之空亡，如甲子旬空戌亥、甲戌旬空申酉、甲申旬空午未、甲午旬空辰巳、甲辰旬空寅卯、甲寅旬空子丑。局中旬空之宫，主其事虚而不实、暂不成事：用神临空亡，主谋事落空或事有隐情；吉格落空则吉而不实，凶格落空反凶而不现。断应期则看空亡填实之时：逢冲空、出空之期，事方有转机。',related:['maxing','qimen-yongshen','shigan-keying']},
  {slug:'tiansanmen',name:'天三门',pinyin:'Tiān Sān Mén',english:'Three Heavenly Gates',category:'qimen',shortDesc:'古传趋避法门，寻太冲小吉从魁三方。',detail:'天三门是奇门遁甲（与六壬相通）中著名的趋避法门，指太冲、小吉、从魁三辰（即卯、未、酉，为六壬十二将中三将）所临之方。其法以月将加时，寻太冲、小吉、从魁三将加临之方位，此三方古人谓有神助，宜于出行、避难、躲灾：如遇兵乱灾祸，向天三门之方趋避，可望逢凶化吉。天三门之说源出古兵家，与地四户并称，为奇门选择方位、趋吉避凶的古老口诀之一，后世多与六壬月将法合用，须通晓月将加时之法。',related:['disihu','zhuke','qimen-dunjia']},
  {slug:'disihu',name:'地四户',pinyin:'Dì Sì Hù',english:'Four Earthly Doors',category:'qimen',shortDesc:'与天三门并列的趋避方位法门。',detail:'地四户是与天三门相配的奇门趋避法门，指由日支起建除十二辰（建、除、满、平、定、执、破、危、成、收、开、闭）之法，选取四个吉辰所临之方位。古法以月建加时寻建除诸辰，于十二辰中取宜于藏身趋避者（诸书多取除、危、定、开四辰，说法不一）为地四户，谓此四方有地气护持，可安身避难。天三门主天时之助，地四户主地利之藏，二者相合，即古传择方趋避的完整法门，与天三门并称，用于躲避灾祸、选择居处。',related:['tiansanmen','zhuke','qimen-dunjia']},
  {slug:'zhuke',name:'主客',pinyin:'Zhǔ Kè',english:'Host and Guest',category:'qimen',shortDesc:'奇门断事之大纲，先分主客再论生克。',detail:'主客是奇门遁甲断事的首要纲领：动者为客、静者为主，先动者为客、后应者为主，主动攻者为客、坐守应战者为主；测人事则以问事一方为主，所测之事、对方为客。断事须先分明主客，再论主客落宫的生克旺衰：主客相生或主旺客衰，主事可成；主客相克，须辨谁克谁，客克主则事外来侵，主克客则我方能制。古人谓奇门断法千变万化，总以主客二字为纲，主客不明则断无准绳，故有主客论为奇门第一义之说。',related:['qimen-yongshen','zhifu','keying']},
  {slug:'wubuyu-shi',name:'五不遇时',pinyin:'Wǔ Bù Yù Shí',english:'Wu Bu Yu Shi (Time of Non-Encounter)',category:'qimen',shortDesc:'时干克日干之时，百事不利之凶时。',detail:'五不遇时是奇门遁甲（及择日学）中的凶时概念，指时辰的天干克制日辰的天干之时。十天干顺序中阳克阳、阴克阴，每隔五干便相克一次，故称五不遇：如甲日庚午时、乙日辛巳时之类，时干庚辛克日干甲乙。五不遇时主事情多阻、百事不顺，古人谓纵得奇门吉格，遇五不遇时亦减力，最忌出兵、上任、远行等大事。断事若用神临五不遇时，主谋事多乖、好事难成，宜另择吉时，故奇门择时首避五不遇。',related:['shijia-qimen','jieqi-dingju','zhuke']},
  {slug:'sanqi-rumu',name:'三奇入墓',pinyin:'Sān Qí Rù Mù',english:'Three Wonders Entering Tomb',category:'qimen',shortDesc:'三奇临墓库之宫，奇受困谋事不遂。',detail:'三奇入墓是奇门遁甲中的凶格之一，指天盘三奇加临其五行墓库之宫：五行之墓为木墓于未、火墓于戌、金墓于丑、水墓于辰，乙木之墓在未（坤宫），丙丁火之墓在戌（乾宫），故乙奇入墓于坤二宫，丙奇、丁奇入墓于乾六宫。三奇入墓，如明珠蒙尘：奇门以三奇为吉，入墓则其吉性受困，主谋事难成、才华不展、好事迟滞。断此格须看入墓深浅，逢冲墓、填实之期，奇可出墓，事方有转机。',related:['sanqi','ding-qi','yi-qi']},
  {slug:'liuyi-jixing',name:'六仪击刑',pinyin:'Liù Yí Jī Xíng',english:'Six Instruments Striking Punishment',category:'qimen',shortDesc:'六仪落于刑地，主暗中受损刑伤之凶格。',detail:'六仪击刑是奇门遁甲中的凶格之一，指天盘六仪加临与所遁之甲相刑之宫，如甲子戊落震三宫（子刑卯）、甲戌己落坤二宫（戌刑未）、甲申庚落艮八宫（申刑寅）之类，谓之六仪击刑。击刑之象主刑伤、破败、暗中受损：测事逢之，主事情有暗亏、官非刑伤或自身失误之象，古人谓击刑之地，谋为多凶，如临门迫更验。断此格须看用神：用神落击刑之宫，主所测之事受刑制，宜防微杜渐；逢吉门吉神，凶性可减。',related:['liuyi','shigan-keying','menpo']},
  {slug:'shigan-keying',name:'十干克应',pinyin:'Shí Gān Kè Yìng',english:'Ten Stems Correspondence',category:'qimen',shortDesc:'天盘干加地盘干百格克应，断事精要。',detail:'十干克应是转盘奇门断事的核心口诀，指天盘三奇六仪加临地盘三奇六仪时所产生的各种吉凶应验，共一百种组合（含伏吟、反吟在内），每组合皆系有断语，如戊加丙青龙返首、丙加戊飞鸟跌穴、丁加癸朱雀投江、庚加己太白入荧之类。断事以用神所乘的天盘干看其加临何干，查相应克应之语，参以门星神宫的旺衰，即可断所测之事的吉凶走向与具体情状。十干克应口诀繁多，为奇门实战者必须精熟的内容。',related:['keying','qinglong-fanshou','feiniao-diexue']},
  {slug:'qinglong-fanshou',name:'青龙返首',pinyin:'Qīng Lóng Fǎn Shǒu',english:'Green Dragon Returning Head',category:'qimen',shortDesc:'戊加丙大吉之格，主谋为顺遂百事可为。',detail:'青龙返首是十干克应中的大吉之格，指天盘甲子戊（戊为青龙）加临地盘丙奇之宫（一说以地盘戊见天盘丙），如青龙回首，故名。戊为六仪之首，丙为三奇之月奇，二者相会主阳气得助：测事逢青龙返首，主谋为顺遂、百事可为，求财得财、求名得名，古人谓此格百事大吉，惟须防物极必反，事成之后不可骄纵。此格若落宫旺相、临吉门吉星，吉力倍增；若逢空亡、入墓或门迫，则吉而减力。',related:['shigan-keying','wu-yi','feiniao-diexue']},
  {slug:'feiniao-diexue',name:'飞鸟跌穴',pinyin:'Fēi Niǎo Diē Xué',english:'Flying Bird Falling into Nest',category:'qimen',shortDesc:'丙加戊大吉之格，主遇难呈祥谋事有成。',detail:'飞鸟跌穴是十干克应中的大吉之格，与青龙返首相为表里，指天盘丙奇加临地盘甲子戊之宫（戊为穴，丙火为鸟，火入土穴，如飞鸟归巢），故名。丙火得戊土之基，主谋事有根、遇难呈祥：测事逢飞鸟跌穴，主事情由难转易、终有所成，古人谓此格百事可为，谋为顺利，凡上任、求财、出行皆吉。此格与青龙返首同为戊丙相会之吉象，一为戊加丙、一为丙加戊，断事皆主大吉，惟亦须观落宫旺衰，忌逢空亡入墓。',related:['shigan-keying','bing-qi','qinglong-fanshou']},
  {slug:'yanbo-diaosou-ge',name:'烟波钓叟歌',pinyin:'Yān Bō Diào Sǒu Gē',english:'Song of the Old Angler',category:'qimen',shortDesc:'奇门最著名的纲领歌诀，习者必读。',detail:'烟波钓叟歌是奇门遁甲最著名的纲领性歌诀，旧题宋代赵普得自烟波钓叟（一说作者即托名钓叟之隐士），故以为名。全歌以七言韵语历述奇门根本法理：阴阳遁之分、节气定局之数、三奇六仪之布、八门九星八神之性与诸吉凶格局，如青龙返首、飞鸟跌穴、三奇入墓等皆见于此歌，为历代奇门家传习的入门总纲。歌诀文辞古奥而义理精深，学者多先诵其辞、后穷其理，与遁甲诸经互参，方能领会奇门全貌。',related:['qimen-dunjia','sanqi-liuyi','bamen']},
  {slug:'jiudun',name:'九遁',pinyin:'Jiǔ Dùn',english:'Nine Duns',category:'qimen',shortDesc:'天地人风云龙虎神鬼九种遁格。',detail:'九遁是奇门遁甲中由三奇、八门、九星、八神依一定组合而成的九种遁格，即天遁、地遁、人遁、风遁、云遁、龙遁、虎遁、神遁、鬼遁。九遁为奇门最吉之格局：天遁主得天时，利上书献策、行兵布阵；地遁主得地利，利安营立寨、修造葬埋；人遁主得人和，利访贤结友、和谈交易；风云龙虎神鬼诸遁亦各应其象，各有所宜。断事得遁，主事情如有神助、可望大成。九遁组合条件严格，古人视为千金不传之秘，习者须熟记其构成。',related:['qimen-dunjia','sanqi','bamen']},
  {slug:'qimen-yongshen',name:'奇门用神',pinyin:'Qí Mén Yòng Shén',english:'Yong Shen in Qi Men',category:'qimen',shortDesc:'断事先取用神，星门神仪各有其所主。',detail:'奇门用神是奇门遁甲断事的第一步：依所测之事选取局中相应的星、门、神、仪为用神，再看其落宫旺衰与生克关系以断吉凶。常用取法：测天时以九星为用，测地理以九宫为用；测人事则门为纲，如测事业、官运看开门，测财运看生门（兼看戊），测婚姻、合作看六合，测病看天芮星，测盗贼看天蓬、玄武，测行人看马星与用神落宫等；又常以值符为贵人、以年命宫参断。用神取准，断事方有根基，故奇门诸法中取用神为第一要义。',related:['zhifu','keying','maxing']},
];
